'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('scramble','Scramble is recorded in English for hurried climbing and confused movement; its deeper formation is uncertain. Later senses include competing hurriedly and breaking something into mixed parts.',[C('scramble.s1','通用','We scrambled up the rocky slope before the rain reached the ridge.','雨到达山脊前，我们手脚并用，迅速爬上了岩坡。','scramble up/over + obstacle','动词，表示用手脚快速攀爬。','climbers move over rocks.','通用'),C('scramble.s2','通用','Fans scrambled for the last tickets as soon as the box office opened.','售票处一开门，粉丝们便急忙争抢最后几张票。','scramble for + limited item','也指人们急切混乱地争抢。','many people compete hurriedly.','通用'),C('scramble.s3','烹饪','She scrambled the eggs with butter and chopped herbs.','她用黄油和切碎的香草炒散了鸡蛋。','scramble eggs; scrambled eggs','动词可指炒鸡蛋或打乱信号。','eggs stirred while cooking.','烹饪'),C('scramble.s4','通用','There was a scramble for seats when the doors finally opened.','门终于打开时，大家一阵慌忙争抢座位。','a scramble for + object','名词指匆忙争抢或艰难攀登。','crowd rushes for places.','通用')],M('The climbers scrambled up the cliff by sitting motionless at its base until the weather cleared.','The climbers scrambled up the cliff by using their hands and feet to climb quickly.','一动不动地坐着不是攀爬。','meaning'),[Q(1,'To scramble up a rocky slope is to…','climb it quickly using hands and feet','walk down it without moving','scrape all the stones off it','Sense 1 describes hurried climbing.','meaning'),Q(2,'Fans scrambled for tickets because…','many people hurriedly competed for a limited number','the tickets had already expired','the fans wanted to scramble eggs','This sense means compete in a confused hurry.','context'),Q(3,'She scrambled the eggs. She…','cooked them while stirring them into small pieces','hid them under a screen','wrote a screenplay about them','Scramble has a cooking sense for eggs.','meaning'),Q(4,'A scramble for seats is…','a hurried, confused effort to get seats','a carefully assigned row of seats','a type of screenplay','The noun describes a rushed competition.','meaning')]);
P('scrap','Scrap is related to Scandinavian forms for a small piece or fragment; it names a small leftover piece, discarded material, or a brief quarrel, and can mean abandon a plan.',[C('scrap.s1','日常','She wrote the address on a scrap of paper and tucked it into her wallet.','她把地址写在一小片纸上，塞进了钱包。','a scrap of + material/food','名词，指纸或食物等的一小片。','small paper fragment.','日常'),C('scrap.s2','回收','The factory sells scrap metal to a recycling company.','工厂把废金属卖给一家回收公司。','scrap metal; go for scrap','名词，指无用后丢弃或回收的材料。','old metal recycled.','回收'),C('scrap.s3','计划','The council scrapped the parking plan after residents raised safety concerns.','居民提出安全担忧后，委员会取消了停车方案。','scrap a plan/project','动词，指决定不再使用计划或丢弃物品。','plan abandoned.','计划'),C('scrap.s4','口语','The two boys had a brief scrap in the playground, then made up.','两个男孩在操场上短暂打了一架，随后又和好了。','have/get into a scrap','名词也指短暂、不太严重的争吵或打斗。','short fight ends.','口语')],M('The council scrapped the plan, meaning it approved it unchanged and began building at once.','The council scrapped the plan, meaning it abandoned it before construction.','scrap a plan表示取消，不是照原计划执行。','meaning'),[Q(1,'A scrap of paper is…','a small piece of paper','a complete notebook','a metal screwdriver','Scrap sense 1 means a small fragment.','meaning'),Q(2,'Scrap metal is metal that…','is no longer useful and may be recycled','has just been installed in a new car','is used to write a screenplay','The material sense refers to discarded metal.','context'),Q(3,'If a project is scrapped, it is…','abandoned or cancelled','expanded with a larger budget','scrutinized but approved unchanged','Scrap as a verb means decide not to use something.','meaning'),Q(4,'A brief scrap between friends is…','a short quarrel or fight','a document written by a scribe','a tiny sea animal','The informal noun can mean a minor fight.','meaning')]);
P('scrape','From Old Norse skrapa “scrape”; scrape means rub something away, injure a surface by friction, succeed with difficulty, or a scraping sound/mark or awkward situation.',[C('scrape.s1','日常','Scrape the dried mud off your boots before entering the house.','进屋前把靴子上干掉的泥刮下来。','scrape something off/from + surface','动词，指用硬边摩擦去除表面物质。','mud removed from boots.','日常'),C('scrape.s2','受伤','He scraped his knee against the rough stone wall.','他的膝盖蹭到了粗糙石墙上，擦破了皮。','scrape a knee/elbow; scrape against','动词也指摩擦造成表面损伤。','skin rubbed against wall.','受伤'),C('scrape.s3','学习','She scraped through the licensing exam with the minimum passing mark.','她勉强以最低及格分通过了执照考试。','scrape through/by; scrape a pass','表示费很大劲才通过或得到某物。','barely meets pass mark.','学习'),C('scrape.s4','通用','The chair leg left a long scrape on the wooden floor.','椅子腿在木地板上留下了一道长长的擦痕。','a scrape on + surface; in a scrape','名词可指摩擦声、痕迹或窘境。','visible surface mark.','通用')],M('He scraped the mud off his boots by pressing it more firmly into the leather and leaving it there.','He scraped the mud off his boots with a stiff brush.','压进皮革并留在那里没有把泥刮除。','meaning'),[Q(1,'To scrape mud off a boot is to…','rub or remove it with a hard edge','paint over it without touching it','tie the boot to a sail','Scrape sense 1 removes material from a surface.','meaning'),Q(2,'He scraped his knee on a wall. His knee…','was rubbed and slightly injured','was carefully protected from contact','was used to write a script','This use describes friction damaging skin.','context'),Q(3,'She scraped through the exam means she…','passed, but only with difficulty','earned the highest score easily','cancelled the exam','Scrape through means just manage to pass.','meaning'),Q(4,'A scrape on the floor is…','a mark made by rubbing','a polished new layer','a sea route','The noun can name a friction mark.','meaning')]);
P('scraper','Scraper is formed from scrape + -er; it names a tool with an edge used to remove paint, ice, mud, or another coating.',C('scraper.s1','工具','He used a plastic scraper to clear frost from the car windscreen.','他用塑料刮片清除汽车挡风玻璃上的霜。','ice/paint scraper; use a scraper to + verb','名词，指刮除表面覆盖物的工具。','tool removes frost.','工具'),M('She used a scraper to add a thick coat of paint onto the wall without removing anything.','She used a scraper to remove the loose paint from the wall.','刮刀用于刮除，不是涂上油漆。','meaning'),[Q(1,'A windscreen scraper is used to…','remove ice or frost from glass','write a film screenplay','tighten a screw','A scraper removes material from a surface.','meaning'),Q(1,'Which item is most likely a scraper?','a flat-edged tool for lifting old paint','a soft brush for adding varnish','a notebook for a scribe','The tool has an edge that scrapes away a coating.','context'),Q(1,'Which phrase is natural?','use a scraper to remove paint','scraper the paint on with','use a scraper to screw the paint','A scraper is used to remove paint.','grammar'),Q(1,'Scraper is formed from scrape plus…','-er','-ness','-ly','The suffix -er names a tool or agent.','word-formation')]);
P('scraping','Scraping is the -ing form of scrape; as a noun it can mean material removed by scraping, and as an adjective it describes a harsh rubbing sound.',[C('scraping.s1','日常','The cook stirred the scrapings from the pan into the sauce.','厨师把锅底刮下来的碎屑搅进了酱汁。','scrapings from + surface','名词，指刮下的一层薄物或碎片。','residue removed from pan.','日常'),C('scraping.s2','声音','A scraping noise from beneath the boat made the crew slow down.','船底传来的刮擦声让船员放慢了速度。','a scraping sound/noise','形容词，描述刮擦时发出的粗糙声音或动作。','rough friction sound.','声音')],M('The cook added the pan’s scrapings even though they were an untouched whole roast sitting beside it.','The cook added the pan’s scrapings, the small bits loosened from its surface.','scrapings是刮下来的碎屑，不是完整烤肉。','meaning'),[Q(1,'Pan scrapings are…','small bits removed from the pan’s surface','a new pan that has never been used','a kind of seaweed','Scraping as a noun can mean material scraped off.','meaning'),Q(2,'A scraping noise under a boat suggests…','something is rubbing against a surface','the boat is perfectly silent','the screenplay is being read aloud','The adjective describes a harsh friction sound.','context'),Q(1,'Which phrase is natural?','a scraping sound','a scrape soundly','a scraping of soundly at','Scraping can modify sound or noise.','grammar'),Q(1,'Scraping is derived from which verb?','scrape','scream','scrubland','It is the -ing form of scrape.','word-formation')]);
P('scraps','Scraps is the plural of scrap; it commonly means small leftover pieces of food or tiny pieces of material.',C('scraps.s1','饮食','The dog waited by the table for scraps left after dinner.','晚饭后，狗守在桌边等着吃剩下的食物碎屑。','food/paper/fabric scraps; scraps of + material','复数名词，指剩下的小块食物或材料碎片。','leftovers on plate.','饮食'),M('The dog ate the scraps, meaning it consumed an untouched three-course meal freshly served to the guests.','The dog ate the scraps, the small leftover pieces from the plates.','scraps指剩余小块，不是完整新上的多道菜。','meaning'),[Q(1,'Food scraps are…','small pieces left over after a meal','freshly cooked whole meals','a tool for removing paint','Scraps are leftover small pieces.','meaning'),Q(1,'Which item could be called scraps?','bits of fabric left after sewing','a complete new coat','a full sack of rye','Tiny leftover material pieces are scraps.','context'),Q(1,'Which phrase is natural?','scraps of food','scraps fooding of','a scrapings food','Scraps of food is a common phrase.','grammar'),Q(1,'Scraps is the plural form of…','scrap','scrape','screed','The plural noun is formed from scrap.','word-formation')]);
P('scratch','Scratch is an old English/Germanic word; it means rub itchy skin, make a thin cut, the mark left, or start with nothing prepared.',[C('scratch.s1','身体','The mosquito bite itched, but she tried not to scratch it.','蚊子叮的地方很痒，但她尽量不去抓。','scratch an itch/bite; scratch at + skin','动词，指用指甲摩擦发痒的皮肤。','fingers rub itchy spot.','身体'),C('scratch.s2','物品','The cat scratched the wooden door while trying to get inside.','猫想进屋时抓花了木门。','scratch a surface; scratch at + object','动词，指在表面划出细痕。','claws mark door.','物品'),C('scratch.s3','物品','A shallow scratch on the watch face disappeared after polishing.','手表表面的一道浅划痕经抛光后消失了。','a scratch on/in + surface','名词，指细长的划痕或轻微伤口。','thin mark polished away.','物品'),C('scratch.s4','创业','They built the community garden from scratch on an empty lot.','他们在一块空地上从零开始建起了社区花园。','from scratch','短语表示从头开始，之前没有现成准备。','project begins with nothing.','创业')],M('They built the garden from scratch using a finished garden plan and fully prepared site exactly as it was.','They built the garden from scratch on an empty lot, doing all the preparation themselves.','from scratch表示从零开始，不是照用已完成的整套准备。','meaning'),[Q(1,'To scratch an itchy bite is to…','rub it with your nails','cover it with a screenplay','scrutinize it from far away','Scratch sense 1 involves rubbing the skin.','meaning'),Q(2,'The cat scratched the door. It…','made marks on the surface with its claws','cleaned the door with soap','sealed the door against water','This sense means make a thin cut or mark.','context'),Q(3,'A scratch on a table is…','a thin mark on its surface','a large seaquake','a complete new table','Scratch as a noun can name a slight mark.','meaning'),Q(4,'Starting a project from scratch means…','beginning without anything already prepared','continuing a nearly finished project','polishing the final surface only','The phrase means from the beginning with no prior setup.','meaning')]);
P('scream','Scream is of Germanic origin; it means make a loud, high cry, the cry itself, or informally something very funny.',[C('scream.s1','情感','She screamed for help when the lights suddenly went out.','灯突然熄灭时，她大声尖叫求救。','scream for help; scream with + emotion','动词，因恐惧、疼痛或愤怒发出高而响的叫声。','fright triggers cry.','情感'),C('scream.s2','声音','A scream from the corridor woke the sleeping guard.','走廊里的一声尖叫惊醒了熟睡的保安。','hear/let out a scream','名词，指一声响亮的高叫。','cry heard in hall.','声音'),C('scream.s3','口语','The comedian’s story about the runaway goat was an absolute scream.','喜剧演员讲的那只逃跑山羊的故事简直笑死人。','be a scream; an absolute scream','口语中可指非常滑稽的人或事。','audience laughs.','口语')],M('She screamed for help in a whisper so quiet that no one could hear her.','She screamed for help in a loud, high cry.','scream是响亮的高叫，不是无人能听见的耳语。','meaning'),[Q(1,'A person may scream because of…','fear, pain, or anger','quietly reading a receipt','a high salary','Scream sense 1 is a loud high cry.','meaning'),Q(2,'A scream from the corridor is…','a loud, high cry','a written screenplay','a sea route','The noun names the cry itself.','context'),Q(3,'If a comedy is “a scream,” it is…','very funny','extremely dull','a medical screening','This informal sense describes something hilarious.','meaning'),Q(1,'Which phrase is natural?','scream for help','scream help by to','scream on help at','For introduces what the person calls for.','grammar')]);
P('screed','Screed comes through Scots/English usage with its deeper origin uncertain; it means a long, dull, often angry piece of writing or a guide strip used to level plaster or concrete.',[C('screed.s1','写作','The blogger posted a long screed against the proposed tax increase.','博主发表了一篇长篇檄文，反对拟议的增税。','a screed against + policy/person','名词，指冗长乏味、常带怒气的讲话或文字。','long angry post.','写作'),C('screed.s2','建筑','The mason checked the screed before smoothing the wet plaster across the wall.','泥瓦匠先检查了刮平导轨，然后才把湿灰浆抹平墙面。','a plaster/concrete screed','建筑中指使灰浆或混凝土表面平整的导条。','guide keeps surface level.','建筑')],M('The mason removed the screed before levelling the plaster, calling it a finished decorative painting on the wall.','The mason used the screed as a guide to level the plaster.','建筑义的screed是导条或找平工具，不是墙面装饰画。','distinction'),[Q(1,'A political screed is likely…','a long, dull, often angry piece of writing','a short friendly greeting','a hand tool for tightening screws','Screed sense 1 describes a lengthy rant.','meaning'),Q(2,'A mason uses a screed to…','guide a level surface of plaster or concrete','write an angry article','make a film screenplay','The construction sense is a leveling guide.','context'),Q(1,'Which phrase is natural?','a screed against the policy','a screed at the policying','a screen against the policy','Against introduces the target of a rant.','grammar'),Q(1,'Which use of screed belongs on a building site?','The worker drew the screed across the wet concrete.','The editor published a screed against taxes.','The novelist read from scripture.','A screed can be a guide for leveling concrete.','meaning')]);
P('screen','Screen is recorded through Middle French escren, “screen”; it names a display or divider, and as a verb means show, examine for risk, or shield from view.',[C('screen.s1','科技','The map appeared on the screen of her phone.','地图显示在她手机的屏幕上。','on a screen; screen displays + image','名词，指电视、电脑或影院的平面显示面。','image shown on display.','科技'),C('screen.s2','家居','A folding screen divided the studio into a sleeping area and a workspace.','一扇折叠屏风把单间隔成睡眠区和工作区。','a screen between/around + areas','名词，指用于隔开或防护的直立屏风或网。','divider separates room.','家居'),C('screen.s3','影视','The local cinema will screen the documentary twice this weekend.','当地影院本周末将放映这部纪录片两场。','screen a film/programme','动词，指播放电影或节目。','cinema shows documentary.','影视'),C('screen.s4','医疗','The clinic screens newborns for several rare conditions.','诊所会对新生儿进行筛查，以发现几种罕见病。','screen someone for + condition/risk','动词，指检查人群以发现疾病或风险。','tests look for conditions.','医疗'),C('screen.s5','自然','Tall trees screened the cottage from the road.','高大的树木遮住了从道路上看小屋的视线。','screen something from + view/danger','动词也可表示遮挡或保护。','trees hide house.','自然')],M('The clinic screened the newborn for a condition by refusing to test or examine the baby.','The clinic screened the newborn by testing for signs of the condition.','screen for illness表示检查筛查，不是拒绝检查。','meaning'),[Q(1,'A phone screen is…','the flat surface that displays images','a room divider made of wood','a tool for tightening screws','Screen sense 1 is an electronic display surface.','meaning'),Q(2,'A folding screen in a studio can…','divide or shield part of the room','show a film to an audience','check a patient for disease','The noun can name a room divider.','context'),Q(3,'The cinema will screen a documentary. It will…','show the film','test the audience for illness','hide the cinema from the road','Screen as a verb can mean show a film.','meaning'),Q(4,'A clinic screens patients for a disease by…','testing them to identify possible cases','showing them a movie','placing a divider between them','This medical sense means examine for a condition.','meaning')]);
P('screenplay','Screenplay combines screen and play; it names the written text of a film, including dialogue and directions for what characters do.',C('screenplay.s1','影视','The director revised the screenplay after the actors read it aloud.','演员朗读后，导演修改了电影剧本。','write/revise/adapt a screenplay','名词，指电影的书面文本，包括对白与动作说明。','text revised before filming.','影视'),M('The director called the screenplay the finished film shown on a cinema screen rather than its written text.','The director called the screenplay the written text used to make the film.','screenplay指书面脚本，不是最终放映的影片本身。','distinction'),[Q(1,'A screenplay contains…','the written dialogue and actions for a film','only the cinema screen’s glass','a list of ticket prices','Screenplay is the written text for a film.','meaning'),Q(1,'An actor reads a screenplay to learn…','what the character says and does','how to tighten a screw','the sea’s salinity','The script gives dialogue and action.','context'),Q(1,'Which phrase is natural?','adapt a novel into a screenplay','screenplay a novel into at','adapt screenplayly to novel','One can adapt a story into a screenplay.','grammar'),Q(1,'Screenplay is a compound of screen and…','play','scribe','scrub','The word combines screen + play.','word-formation')]);
P('screw','From Old French escroue “nut, screw,” with earlier origins uncertain; screw is a spiral-threaded fastener, to fasten or twist shut, or informally to spoil something.',[C('screw.s1','工具','One screw had worked loose, so the cabinet door sagged.','一颗螺丝松了，柜门因此下垂。','a wood/metal screw; tighten a screw','名词，指带螺旋纹、用于固定物体的金属钉。','loose fastener.','工具'),C('screw.s2','工具','Screw the lid on tightly before putting the jar in the bag.','把盖子拧紧后再把罐子放进袋子里。','screw something on/off; screw something into','动词，表示用螺钉固定或旋转拧紧。','lid twisted closed.','工具'),C('screw.s3','口语','I screwed up the schedule by entering the wrong departure time.','我把出发时间输错，把日程安排搞砸了。','screw up + task/plan','口语短语表示因严重失误把事情弄坏。','mistake spoils schedule.','口语')],M('She screwed the lid on by leaving it loose and allowing the liquid to spill out.','She screwed the lid on tightly to stop the liquid from spilling.','screw the lid on tightly表示旋紧，不是留松。','meaning'),[Q(1,'A metal screw is…','a spiral-threaded fastener','a flat piece of screen glass','a sea animal','The noun sense describes a threaded pin.','meaning'),Q(2,'To screw the lid on is to…','twist it closed','cut it into small pieces','screen a film','Screw as a verb can mean twist a cap or lid shut.','context'),Q(3,'If I screwed up the schedule, I…','spoiled it by making a bad mistake','made it more accurate','turned it into scripture','Screw up is informal for mess up.','meaning'),Q(2,'Which phrase is natural?','screw the lid on','screw the lid with by','screw on the lid tightlyly','The common pattern is screw the lid on.','grammar')]);
P('screwdriver','Screwdriver combines screw and driver; it is a hand tool whose shaped metal tip turns a screw.',C('screwdriver.s1','工具','She used a Phillips screwdriver to tighten the hinge screws.','她用十字螺丝刀拧紧了铰链上的螺钉。','a Phillips/flat-head screwdriver; use a screwdriver to + verb','名词，指用来旋转螺丝的手工具。','tip fits screw head.','工具'),M('He reached for a screwdriver to hammer the nail into the board with its blunt handle.','He reached for a hammer to drive the nail into the board.','螺丝刀用于拧螺钉；钉钉子应使用锤子。','distinction'),[Q(1,'A screwdriver is designed to…','turn a screw using a fitted tip','cut a screenplay into pages','measure sea depth','The tool fits a screw head and turns it.','meaning'),Q(1,'Which screwdriver fits a cross-shaped screw head?','a Phillips screwdriver','a flat-head screwdriver','a seafarer','Phillips tips fit cross-shaped screw heads.','context'),Q(1,'Which phrase is natural?','tighten a screw with a screwdriver','tighten a screw by a screenplay','screwdriver the screw with','With introduces the tool used.','grammar'),Q(1,'The second part of screwdriver, driver, relates to…','turning or driving a fastener','a person who sails a ship','a paper scroll','The tool turns screws into or out of material.','word-formation')]);
P('scribble','Scribble is related to Latin scribere “write,” through forms meaning scratch or write carelessly; it means write quickly in untidy, hard-to-read marks.',C('scribble.s1','写作','He scribbled the gate code on the back of a receipt before the ink ran out.','墨水用完前，他把门禁密码潦草地写在收据背面。','scribble something on + surface; scribble down','动词，指匆忙写得潦草难辨。','quick untidy note.','写作'),M('She scribbled the address in neat, carefully formed letters that everyone could read easily.','She scribbled the address quickly in untidy letters that were difficult to read.','整齐清楚的书写与scribble的潦草义不符。','distinction'),[Q(1,'To scribble a phone number is to…','write it quickly and untidily','print it in a perfect typeface','erase it from a screen','Scribble describes hurried, messy writing.','meaning'),Q(1,'Where might someone scribble a reminder?','on the back of a receipt','on a completed stone sculpture','inside a sealed screw','A scrap surface is often used for a quick note.','context'),Q(1,'Which phrase is natural?','scribble down a note','scribble a note downly','scribble to a note at','One can scribble down information.','collocation'),Q(1,'Scribble is related to the Latin verb meaning…','write','sail','screen','The word is connected with Latin scribere.','word-formation')]);
P('scribbler','Scribbler is formed from scribble + -er; it is a dismissive term for someone who writes carelessly or produces poor work.',C('scribbler.s1','写作','The critic dismissed the anonymous columnist as a scribbler who never checked her facts.','评论家把那位匿名专栏作者贬称为一个从不核实事实的潦草写手。','a mere scribbler; dismiss someone as a scribbler','名词，常带贬义，指写作草率或作品低劣的人。','critic belittles writer.','写作'),M('The editor called the meticulous historian a scribbler because every page was carefully researched and revised.','The editor called the careless columnist a scribbler because the writing was poorly checked.','仔细研究修订的作者不符合草率写手的贬义。','meaning'),[Q(1,'A scribbler is usually…','someone who writes carelessly or poorly','a professional sculptor','a tool for tightening screws','The noun is often a dismissive label for a weak writer.','meaning'),Q(1,'Calling a novelist “a mere scribbler” signals…','disapproval of the novelist’s writing','a formal job promotion','admiration for perfect scholarship','Mere scribbler is a belittling expression.','context'),Q(1,'Which phrase is natural?','dismiss him as a scribbler','dismiss him a scribblering','dismiss as him to scribble','The construction is dismiss someone as a scribbler.','grammar'),Q(1,'Scribbler is formed from scribble plus…','-er','-ful','-ity','The suffix -er names a person associated with writing.','word-formation')]);
P('scribe','From Latin scriba “writer, clerk,” related to scribere “write”; a scribe was someone employed, especially in the past, to copy documents by hand.',C('scribe.s1','历史','The royal scribe copied the treaty onto parchment by hand.','王室抄写员把条约手工誊写在羊皮纸上。','a court/royal scribe; scribe documents','名词，指旧时受雇抄录文书的人。','document copied manually.','历史'),M('The medieval scribe copied the manuscript by hand, although the word means a person who carved stone statues.','The medieval scribe copied the manuscript by hand.','scribe指抄写员，不是雕塑家。','distinction'),[Q(1,'A medieval scribe was employed to…','copy documents by hand','repair a ship’s seaway','sell goods in a salon','Scribe sense 1 is a hand-copying clerk.','meaning'),Q(1,'A scribe might write on…','parchment','a screwdriver tip','a seabed','Parchment was a writing surface for manuscript copying.','context'),Q(1,'Which phrase is natural?','a royal scribe copied the record','a royal scribe was copied the record','a royal scribe copying recordly','The scribe is the agent who copies the document.','grammar'),Q(1,'Scribe is related to Latin scribere, meaning…','write','scrub','sail','The Latin family concerns writing.','word-formation')]);
P('script','From Latin scriptum “something written,” from scribere “write”; script is a performance text, handwriting, a writing system, or the verb to write a text.',[C('script.s1','影视','The actors rehearsed the script before filming the final scene.','演员们在拍摄最后一幕前排练了剧本。','a film/play script; read/rehearse a script','名词，指电影、戏剧或广播的书面台词。','actors use written lines.','影视'),C('script.s2','书写','The doctor’s hurried script was difficult for the pharmacist to read.','医生匆忙的手写字迹让药剂师难以辨认。','in someone’s script; handwritten script','名词也指与印刷体相对的手写字体。','handwriting hard to read.','书写'),C('script.s3','文字','The inscription uses the Arabic script rather than Latin letters.','这段铭文使用阿拉伯文字体系，而不是拉丁字母。','Arabic/Cyrillic script; write in a script','名词也指一种语言使用的书写符号系统。','writing system identified.','文字'),C('script.s4','影视','She scripted the museum audio tour for visitors.','她为博物馆访客撰写了语音导览文稿。','script a speech/programme','动词，表示为影片、节目或讲话撰写文本。','writer prepares spoken text.','影视')],M('The Arabic script is a film’s dialogue document, not a system of written characters.','The Arabic script is a system of written characters used to write Arabic.','此处script指书写体系，不是影视台词。','distinction'),[Q(1,'An actor studies a script to learn…','the written dialogue and actions','the ocean’s salinity','how to repair a seabed','Script sense 1 is a performance text.','meaning'),Q(2,'The doctor’s script was hard to read means…','the doctor’s handwriting was unclear','the doctor’s film was difficult to screen','the doctor used Arabic letters','Script can refer to handwriting.','context'),Q(3,'Arabic script is…','a system of written characters','a screenplay about Arabic history','a sealed container','Sense 3 is a writing system.','meaning'),Q(4,'She scripted the audio tour means she…','wrote the text for it','read someone’s handwriting','cancelled the tour','Script as a verb means write a performance text.','meaning')]);
P('scripture','From Latin scriptura “writing,” from scribere “write”; scripture means the sacred writings of a religion, especially the Bible.',C('scripture.s1','宗教','The teacher asked the class to compare the passage with other scripture.','老师让全班把这段文字与其他宗教经典进行比较。','sacred scripture; a passage from scripture','不可数或集合名词，指宗教神圣文献。','religious texts compared.','宗教'),M('The congregation called the Bible scripture, then explained that scripture means an ordinary shopping receipt.','The congregation called the Bible scripture, meaning a sacred religious text.','scripture指宗教经典，不是普通收据。','meaning'),[Q(1,'Scripture is…','the sacred writings of a religion','a casual note on a receipt','a tool used by a sculptor','Scripture names religiously sacred texts.','meaning'),Q(1,'A passage from scripture is likely found in…','a holy text such as the Bible','a salary bill only','a seaport map','The word refers especially to sacred writings.','context'),Q(1,'Which phrase is natural?','a passage from scripture','scripture for a passageing','a scripturely passage to','From identifies the source text.','grammar'),Q(1,'Scripture traces to a Latin word meaning…','writing','salt','sea','Its Latin source scriptura means writing.','word-formation')]);
P('scriptwriter','Scriptwriter combines script and writer; it names someone whose job is writing dialogue and staged action for film, television, radio, or theatre.',C('scriptwriter.s1','影视','The scriptwriter changed the final scene after the test audience found it confusing.','试映观众觉得结尾一幕令人困惑后，编剧改写了它。','a television/film scriptwriter; work as a scriptwriter','名词，指为影视或舞台作品撰写脚本的人。','writer revises scene text.','影视'),M('The scriptwriter operated the cinema projector but did not write any dialogue or action for the film.','The scriptwriter wrote the dialogue and actions that actors performed.','放映员操作投影设备；scriptwriter负责写文本。','distinction'),[Q(1,'A scriptwriter’s main job is to…','write the spoken and staged text of a production','repair the theatre’s projector','sell tickets at the cinema','Scriptwriters create text performed by actors.','meaning'),Q(1,'Why might a scriptwriter revise a scene?','An audience found the scene confusing.','A seagull landed on the seabed.','The salary bill was lower.','Revisions improve the written production.','context'),Q(1,'Which phrase is natural?','a scriptwriter for television','a scriptwriter of to televisioning','a writer scripted television person','A scriptwriter can work for television.','grammar'),Q(1,'Scriptwriter combines script with…','writer','screen','scribe','The compound names a person who writes scripts.','word-formation')]);
P('scroll','Scroll is related to Old French escroe “roll, strip of parchment”; it is a rolled writing sheet or the action of moving content across a screen.',[C('scroll.s1','历史','The curator carefully unrolled the ancient scroll to read its damaged lines.','馆长小心展开古老卷轴，阅读上面受损的文字。','an ancient scroll; unroll a scroll','名词，指卷起来用于书写的纸或其他材料。','rolled document opened.','历史'),C('scroll.s2','科技','Scroll down to the bottom of the page to find the references.','向下滚动到页面底部就能找到参考文献。','scroll up/down/through + page','动词，指在屏幕上上下或横向移动文本或图像。','user moves through page.','科技')],M('She scrolled down the web page by printing it on a long roll of parchment.','She scrolled down the web page using the mouse wheel.','屏幕上移动内容是动词scroll；纸卷是名词scroll。','distinction'),[Q(1,'An ancient scroll is…','a rolled sheet used for writing','a modern screen divider','a metal screw','Scroll sense 1 names a rolled document.','meaning'),Q(2,'To scroll down a page is to…','move its content lower on the screen','roll up a paper manuscript','seal a jar tightly','The verb describes moving displayed content.','context'),Q(1,'Which phrase is natural?','scroll down to the bottom','scroll at the bottom down of','scrolling the bottom into','Down marks the direction of screen movement.','grammar'),Q(1,'Which sentence uses scroll as a noun?','The scroll was kept in a dry case.','Scroll down to read the next section.','She scrolled through the page.','The first sentence names a physical rolled document.','meaning')]);
P('scrounge','Scrounge is informal slang recorded in English in the nineteenth century; its deeper origin is uncertain. It means obtain things, often by persistently asking others.',[C('scrounge.s1','口语','He scrounged a cigarette from a stranger while waiting for the delayed bus.','等晚点的公交车时，他向陌生人讨了一支烟。','scrounge something from someone; scrounge around for','动词，常带贬义，表示向人讨要免费的东西或钱。','asks stranger for item.','口语')],M('He scrounged a cigarette from a stranger by paying full price at the shop and receiving a receipt.','He scrounged a cigarette by asking the stranger to give him one for free.','付全价购买不是向别人讨要免费物品。','distinction'),[Q(1,'To scrounge a cigarette from someone is to…','ask them to give you one, usually for free','sell them a pack at full price','write a script on one','Scrounge means obtain something by asking, often annoyingly.','meaning'),Q(1,'Which person is scrounging?','A traveler repeatedly asks others for spare change.','A cashier charges each buyer the marked price.','A scribe copies a legal document.','Repeatedly asking for free money fits scrounging.','context'),Q(1,'Which phrase is natural?','scrounge a meal from a friend','scrounge a friend to a meal from','scrounging of a meal by','From introduces the person the item is obtained from.','grammar'),Q(1,'Scrounge is best labeled as…','informal and often disapproving','a formal legal term for a written seal','an adjective for a polished sculpture','It is a colloquial verb with a negative shade.','usage')]);
P('scrub','Scrub is related to Dutch schrobben and Germanic words for rubbing; it means clean by hard rubbing, cancel a planned activity, or low bushes growing together.',[C('scrub.s1','家务','She scrubbed the kitchen floor with a brush until the dried mud came off.','她用刷子用力擦洗厨房地板，直到干泥被清除。','scrub something clean; scrub at + stain','动词，指用刷子和水用力摩擦清洁。','brush removes dirt.','家务'),C('scrub.s2','计划','The airline scrubbed the test flight because high winds made takeoff unsafe.','强风导致起飞不安全，航空公司取消了试飞。','scrub a flight/launch/plan','动词也可指临时取消计划好的活动。','flight called off.','计划'),C('scrub.s3','自然','A narrow track wound through scrub before reaching the open grassland.','一条窄径穿过低矮灌丛，通向开阔草地。','scrub bushes/vegetation; scrubland','名词，指成片生长的低矮灌木和小树。','low woody plants.','自然')],M('She scrubbed the floor by gently sprinkling perfume on it and leaving every stain untouched.','She scrubbed the floor by rubbing it hard with a brush and water.','scrub强调用力摩擦清洁，不是只喷香水。','meaning'),[Q(1,'To scrub a floor is to…','clean it by rubbing hard with a brush','screen a film on it','cover it with a screenplay','Scrub sense 1 means clean through vigorous rubbing.','meaning'),Q(2,'If an airline scrubs a flight, it…','cancels the planned flight','cleans the aircraft with a brush','sends it into a scuffle','Scrub as a verb can mean cancel an event.','context'),Q(3,'The track passed through scrub. It passed through…','low bushes and small trees','a high forest of mature timber only','a theatre screen','Scrub as a noun describes low woody vegetation.','meaning'),Q(1,'Which phrase is natural?','scrub the stain off','scrub the stain to offing','scrub at stain from to','One can scrub a stain off a surface.','grammar')]);
P('scrubland','Scrubland combines scrub and land; it is dry or poor country where low bushes and small trees grow instead of tall timber.',C('scrubland.s1','地理','Goats grazed across the scrubland where scattered low bushes covered the dry soil.','山羊在灌木丛生的土地上吃草，那里干燥土壤上散布着低矮灌木。','dry/poor scrubland; scrubland habitat','名词，指以灌丛而非高大树木为主要植被的土地。','low shrubs dominate.','地理'),M('The ecologist called the dense, tall timber forest scrubland even though no low bushes grew there.','The ecologist called the dry area of low bushes and small trees scrubland.','以高大森林为主的区域不符合scrubland的植被特征。','distinction'),[Q(1,'Scrubland is land mainly covered by…','low bushes and small trees','deep ocean water','large buildings','Scrubland is defined by scrub rather than tall timber.','meaning'),Q(1,'A goat grazing on dry scrubland is likely eating…','low shrubs','seafood','a script','Shrubs are characteristic vegetation there.','context'),Q(1,'Which phrase is natural?','a scrubland habitat','a scrublandly habitat','a habitat of scrublandings','Scrubland commonly modifies habitat.','grammar'),Q(1,'Scrubland combines scrub with…','land','line','sail','The compound names land where scrub grows.','word-formation')]);
P('scruffy','Scruffy is recorded from the nineteenth century for an untidy or worn appearance; the history of scruff is uncertain. It describes someone or something messy or poorly kept.',C('scruffy.s1','外貌','He arrived in a scruffy jacket with muddy cuffs and untidy hair.','他穿着一件皱巴巴的夹克、袖口沾泥，头发也很凌乱地赶到。','scruffy clothes/appearance; look scruffy','形容词，表示外表磨损、凌乱或不整洁。','clothes and hair untidy.','外貌'),M('The visitor looked scruffy in a spotless pressed suit and freshly polished shoes.','The visitor looked scruffy in worn clothes and muddy shoes.','一身熨烫整洁、鞋子锃亮与scruffy相反。','distinction'),[Q(1,'A scruffy jacket looks…','worn or untidy','newly pressed and spotless','made of seaweed','Scruffy describes a messy or poorly kept appearance.','meaning'),Q(1,'Which scene suggests someone looks scruffy?','Muddy boots and a stained, wrinkled coat','A clean suit and polished shoes','A sealed and labeled parcel','Worn and messy clothing matches the adjective.','context'),Q(1,'Which phrase is natural?','a scruffy old coat','a scruffily old coat','a scruffy of old coat','Scruffy is an adjective modifying coat.','grammar'),Q(1,'Scruffy describes…','appearance or condition','a person counting ballots','a sea route','It refers to an untidy or worn look.','meaning')]);
P('scruple','From Latin scrupulus “small sharp stone,” later a source of mental unease; scruple means a moral hesitation or, in an older use, a very small amount.',[C('scruple.s1','道德','She had no scruple about reporting the safety violation to the regulator.','她毫不犹豫地把安全违规情况报告给监管机构。','have/have no scruple about + action','名词，指阻止人做自认为不道德事情的顾虑。','reporting seen as right.','道德'),C('scruple.s2','书面','The witness said there was not a scruple of truth in the forged confession.','证人说那份伪造供词里连一丁点真话都没有。','not a scruple of + substance/quality','旧式用法中指极少量。','not even a tiny amount.','书面')],M('She had no scruple about stealing the money because she felt deeply troubled and refused to do it.','She had no scruple about stealing the money because she felt no moral hesitation.','no scruple表示没有道德顾虑，不是心存强烈顾虑。','meaning'),[Q(1,'A moral scruple may stop someone from…','doing something they believe is wrong','scrutinizing an account carefully','climbing a cliff','Scruple sense 1 is a moral hesitation.','meaning'),Q(2,'“Not a scruple of truth” means…','not even a tiny amount of truth','a very large quantity of evidence','a brief quarrel','The older sense scruple can mean a very small amount.','context'),Q(1,'Which phrase is natural?','have scruples about lying','have scruples for to lying','scruple a lie into','About introduces the action that causes hesitation.','grammar'),Q(1,'The Latin source scrupulus referred to…','a small sharp stone','a sea bird','a writing system','The word developed from the image of a sharp pebble causing unease.','word-formation')]);
P('scrupulous','From Latin scrupulosus, from scrupulus “small sharp stone”; scrupulous describes meticulous accuracy or moral care that avoids dishonesty.',[C('scrupulous.s1','工作','The lab keeps scrupulous records of every sample and temperature change.','实验室对每个样本和温度变化都做了极其细致的记录。','scrupulous records/attention; scrupulous about + detail','形容词，表示细心到每个细节都力求正确。','records meticulously detailed.','工作'),C('scrupulous.s2','道德','He was too scrupulous to accept a gift from a company bidding for his contract.','他为人正直，不肯收受竞标公司的礼物。','scrupulous about + ethics; too scrupulous to + verb','也表示道德谨慎，不愿做不诚实的事。','refuses possible bribe.','道德')],M('The scrupulous auditor ignored missing receipts and accepted a bribe without recording it.','The scrupulous auditor checked the missing receipts and refused the bribe.','忽略证据并受贿与细致且守道德相反。','distinction'),[Q(1,'A scrupulous record is…','carefully accurate in every detail','carelessly incomplete','a document written in a screenplay','Scrupulous sense 1 emphasizes meticulous care.','meaning'),Q(2,'A scrupulous official refuses a bribe because the official…','is careful to do what is morally right','is trying to scrounge for money','cannot read a screen','Sense 2 concerns ethical conduct.','context'),Q(1,'Which phrase is natural?','scrupulous about accuracy','scrupulous accuracying by','scrupulous to accuracyly','Scrupulous about introduces the standard being observed.','grammar'),Q(1,'Scrupulous derives from Latin scrupulosus, connected with…','scrupulus, a small sharp stone','scriptum, a written text','sculptura, a carved statue','The historical image is a small pebble causing mental unease.','word-formation')]);
P('scrupulously','Scrupulously is formed from scrupulous + -ly; it means with exceptional care for accuracy, fairness, or moral correctness.',C('scrupulously.s1','工作','The accounts were scrupulously checked before the report was released.','报告发布前，账目经过了极其仔细的核查。','scrupulously check/record/follow','副词修饰动作，表示谨慎细致或严格守规范。','audit checks all entries.','工作'),M('The accounts were scrupulously checked by skipping every entry and making no comparison.','The accounts were scrupulously checked by comparing every entry with its receipt.','跳过所有条目并未仔细核查。','meaning'),[Q(1,'To check accounts scrupulously is to check them…','with great care and attention to accuracy','by ignoring most entries','only after destroying the receipts','Scrupulously means very carefully and conscientiously.','meaning'),Q(1,'Which sentence uses scrupulously correctly?','The researcher scrupulously recorded each result.','The researcher scrupulous recorded each result.','The researcher recorded scrupulouslyness each result.','The adverb modifies recorded.','grammar'),Q(1,'A scrupulously fair judge would…','apply the rules carefully and impartially','accept secret gifts from one side','skip the evidence','Scrupulous fairness requires careful ethical conduct.','context'),Q(1,'Scrupulously is formed by adding -ly to…','scrupulous','scruple','scrutinize','The adverb derives from the adjective scrupulous.','word-formation')]);
P('scrutineer','Scrutineer is chiefly British usage for an appointed person who checks a ballot count or watches a procedure for irregularities.',C('scrutineer.s1','选举','Each candidate appointed a scrutineer to observe the ballot count.','每位候选人都指定了一名监票人监督计票。','appoint a scrutineer; a scrutineer at a count','名词，指监督计票或程序合规的人。','official observes counting.','选举'),M('The scrutineer changed the ballot totals alone in a closed room instead of observing the count.','The scrutineer watched the ballot count and reported any irregularities.','监票人的职责是监督计票，而非私自改票数。','meaning'),[Q(1,'A scrutineer at an election…','observes or checks the ballot count','writes the candidates’ screenplay','repairs the ballot box with a screwdriver','A scrutineer checks the counting procedure.','meaning'),Q(1,'Why appoint a scrutineer?','To help detect irregularities in the count.','To decide which sea lion wins a race.','To season the voting papers.','Observation supports a fair procedure.','context'),Q(1,'Which phrase is natural?','appoint a scrutineer at the count','scrutineer the count by appointmented','appoint a count to scrutineerly','A person may be appointed to supervise a count.','grammar'),Q(1,'The word scrutineer is commonly used in…','British English','only ancient Greek','marine biology','It is a chiefly British term for an election observer.','usage')]);
P('scrutinise','Scrutinise is the British spelling variant of scrutinize, from Latin scrutari “search, examine”; it means inspect something closely.',C('scrutinise.s1','工作','Auditors scrutinised every invoice before approving the reimbursement.','审计人员批准报销前仔细检查了每一张发票。','scrutinise documents/details; scrutinise something for + issue','动词，表示密切仔细地查看以发现问题。','invoice inspected carefully.','工作'),M('The auditors scrutinised the invoices by approving them without opening or reading any one of them.','The auditors scrutinised the invoices by checking each amount and receipt closely.','不打开、不阅读就批准并非仔细检查。','meaning'),[Q(1,'To scrutinise an invoice is to…','examine it very carefully','throw it away without reading','write it as a screenplay','Scrutinise means inspect closely.','meaning'),Q(1,'Which sentence is correct in British spelling?','The panel scrutinised the evidence.','The panel scrutinisedly evidence.','The panel scrutinise the evidence yesterday.','Scrutinised is the past form of scrutinise.','grammar'),Q(1,'The committee scrutinised the plan for safety problems. It…','looked for problems by examining it closely','cancelled it without review','turned it into a seaway','The phrase scrutinise for identifies what reviewers seek.','context'),Q(1,'Scrutinise and scrutinize are…','British and American spelling variants of the same verb','two unrelated words with opposite meanings','noun and adjective forms','Both spellings mean examine closely.','spelling')]);
P('scrutinize','From Latin scrutari “search, examine”; scrutinize means examine documents, plans, or a person’s face with close attention.',[C('scrutinize.s1','工作','The bank will scrutinize the application before releasing the loan.','银行放款前会仔细审查这份申请。','scrutinize a document/plan; scrutinize something for + detail','动词，表示非常仔细地检查文件或计划。','loan application reviewed.','工作'),C('scrutinize.s2','观察','She scrutinized his face for signs that he recognized the name.','她仔细端详他的脸，寻找他认出那个名字的迹象。','scrutinize someone’s face; scrutinize someone for + sign','动词也可指仔细端详一个人或其表情。','watch for facial reaction.','观察')],M('The bank scrutinized the loan application by refusing to read any of its pages.','The bank scrutinized the loan application by checking its figures and supporting documents.','不阅读申请就不可能仔细审查。','meaning'),[Q(1,'A bank scrutinizes an application when it…','examines it carefully before deciding','approves it without checking','turns it into a seaquake','Scrutinize means examine closely.','meaning'),Q(2,'She scrutinized his face for a reaction. She…','looked at his face closely','wrote a reaction into a script','searched the seabed','This is the face-inspection sense.','context'),Q(1,'Which phrase is natural?','scrutinize the evidence','scrutinize at the evidencely','scrutinizing to evidence by','Scrutinize takes the material examined as its direct object.','grammar'),Q(2,'Which sentence uses scrutinize in sense 2?','He scrutinized her expression for a clue.','The auditor scrutinized the accounts.','The committee scrutinized the proposal.','The first option describes close attention to a person’s face.','meaning')]);
P('scrutiny','From Latin scrutari “search, examine”; scrutiny is close inspection to judge something or critical attention from officials or the public.',[C('scrutiny.s1','工作','The accounts came under scrutiny after several payments were duplicated.','几笔款项重复支付后，账目受到了仔细审查。','under scrutiny; close scrutiny of + item','名词，指为了判断而进行的密切检查。','duplicates trigger audit.','工作'),C('scrutiny.s2','公共事务','The minister’s travel expenses faced public scrutiny after the report was released.','报告公布后，部长的差旅开支受到公众审视。','public/media/official scrutiny','也指公众或官员带有批判性的关注。','public questions expenses.','公共事务')],M('The payments remained beyond scrutiny because auditors examined every record and reported all irregularities.','The payments came under scrutiny when auditors examined the records for irregularities.','接受仔细检查就是受到scrutiny，不是处于审查之外。','meaning'),[Q(1,'An account under scrutiny is…','being examined closely','being hidden from every reviewer','a tool for scraping paint','Scrutiny means close inspection.','meaning'),Q(2,'Public scrutiny of an official means…','the public is paying critical attention','the official is screening a film','the public is sailing away','Sense 2 concerns public or official attention.','context'),Q(1,'Which phrase is natural?','under close scrutiny','under scrutinyly close','scrutiny to a close under','Under scrutiny means subject to careful review.','collocation'),Q(1,'Scrutiny is related to Latin scrutari, meaning…','search or examine','write a sacred text','rub a floor','The word traces to a verb for searching or examining.','word-formation')]);
P('scuba','Scuba is an acronym formed from “self-contained underwater breathing apparatus”; it names the equipment a diver wears to breathe underwater.',C('scuba.s1','潜水','The instructor checked each diver’s scuba before they entered the water.','教练在潜水员下水前检查了每个人的水肺装置。','scuba equipment; scuba diving','名词，指潜水员佩戴的压缩空气瓶、调节器和软管装置。','gear checked before dive.','潜水'),M('The diver checked the scuba, a lightweight paper map that supplies no air underwater.','The diver checked the scuba, the breathing equipment used underwater.','scuba是水下呼吸装置，不是纸地图。','meaning'),[Q(1,'Scuba is…','a diver’s self-contained underwater breathing apparatus','a type of seaweed','a small sail for a boat','The acronym names underwater breathing equipment.','meaning'),Q(1,'Before a scuba dive, an instructor should check…','the diver’s air tanks and regulator','the screenplay’s punctuation','the salinity of the diver’s shoes','Those components are part of scuba gear.','context'),Q(1,'Which phrase is natural?','scuba equipment','scuba to equipmenting','equipment of scubas at','Scuba equipment names the diver’s breathing gear.','collocation'),Q(1,'The letters in scuba stand for…','self-contained underwater breathing apparatus','screened cinema under boat access','salt-containing underwater beach algae','Scuba originated as an acronym for the apparatus.','word-formation')]);
P('scud','Scud is recorded from Middle English for moving quickly; its deeper origin is uncertain. It means race along, especially when wind drives clouds or a boat.',C('scud.s1','天气','Low clouds scudded across the moon as the wind strengthened.','风势增强时，低云迅速掠过月亮。','clouds scud across/along + sky','动词，指云或船等被风推动而快速移动。','wind drives clouds.','天气'),M('The clouds scudded across the sky by remaining fixed in one place throughout the night.','The clouds scudded across the sky as a strong wind drove them quickly.','固定不动与快速掠过相反。','meaning'),[Q(1,'Clouds that scud across the sky…','race along quickly, often driven by wind','remain motionless','form a screenplay','Scud describes rapid movement.','meaning'),Q(1,'A boat may scud when…','the wind drives it quickly over the water','it is tied securely to shore','its sealer dries','Wind can propel a boat in the scud sense.','context'),Q(1,'Which phrase is natural?','clouds scudded across the moon','clouds scud to a moonly','clouds were scud acrossing','Scud can be used with clouds moving across the sky.','grammar'),Q(1,'The deeper origin of scud is…','uncertain','Latin for a sacred text','an acronym for dive gear','The word’s earlier formation is not confidently known.','word-formation')]);
P('scuff','Scuff is an informal verb of uncertain deeper origin; it means drag or rub shoes along a surface, or leave a friction mark.',C('scuff.s1','日常','He scuffed his new shoes on the rough concrete step.','他的新鞋在粗糙的水泥台阶上蹭出了磨痕。','scuff shoes; scuff against/on + surface','动词，指拖擦鞋子或摩擦损伤表面。','friction marks leather.','日常'),M('She scuffed the polished floor by walking across it without touching it.','She scuffed the polished floor by dragging her shoes across its surface.','不接触地面就不会摩擦出痕迹。','meaning'),[Q(1,'To scuff a shoe is to…','rub or drag it against a surface','seal it inside a jar','write a script on it','Scuff involves friction against a surface.','meaning'),Q(1,'Which action could scuff a polished floor?','Dragging a shoe sole across it','Walking above it without contact','Painting a screen behind it','The dragging sole can leave a mark.','context'),Q(1,'Which phrase is natural?','scuff a shoe on the step','scuff a step to shoe at','scuffly the shoe with','On introduces the surface rubbed against.','grammar'),Q(1,'Scuff is closest in meaning to…','rub and mark by friction','read a sacred text','sculpt from stone','Scuff describes scraping contact that can leave a mark.','meaning')]);
P('scuffle','Scuffle is of uncertain origin; as a noun it means a brief confused fight, and as a verb it can mean move with feet dragging.',[C('scuffle.s1','新闻','A brief scuffle broke out outside the stadium after the match.','比赛后，体育场外发生了一场短暂的混乱打斗。','a scuffle between/with + people','名词，指人群中的短暂、混乱打斗。','short fight begins.','新闻'),C('scuffle.s2','动作','The tired child scuffled along in shoes that were too large.','疲惫的孩子穿着过大的鞋子，拖着脚往前蹭。','scuffle along/across + place','动词，指走路时脚没有抬起来、在地面拖蹭。','feet drag while walking.','动作')],M('A scuffle broke out, but everyone stood peacefully apart and nobody pushed or fought.','A scuffle broke out when several people pushed and struggled briefly.','没有任何冲突动作就不能称为打斗。','meaning'),[Q(1,'A scuffle outside a stadium is…','a short, confused fight','a planned sculpture display','a vote count','Scuffle as a noun is a brief disorderly fight.','meaning'),Q(2,'A child scuffled along in oversized shoes by…','dragging the feet while walking','running elegantly on tiptoe','sailing across a lake','The verb sense describes dragging steps.','context'),Q(1,'Which phrase is natural?','a scuffle between two groups','a scuffle of two groupingly','a group scuffled noun between','Between identifies the people involved in a scuffle.','grammar'),Q(1,'Which is a likely sign of a scuffle?','brief pushing and struggling','quietly copying a manuscript','carefully checking an invoice','A scuffle is a small confused physical fight.','meaning')]);
P('sculpt','From Latin sculpere “carve”; sculpt means make a sculpture or shape material by carving, modelling, or similar artistic work.',C('sculpt.s1','艺术','The artist sculpted a horse from a single block of pale stone.','艺术家用一整块浅色石头雕出了一匹马。','sculpt something from/in + material','动词，表示雕刻或塑形制作雕塑。','figure carved from stone.','艺术'),M('The artist sculpted the horse by leaving the stone block completely unchanged.','The artist sculpted the horse by carving the stone into a recognizable shape.','不对材料进行切削或塑形就没有完成雕刻。','meaning'),[Q(1,'To sculpt a figure from stone is to…','carve or shape the material into an artwork','scrutinize a document','scrub the floor','Sculpt means create a shaped work of art.','meaning'),Q(1,'Which material could someone sculpt?','a block of marble','a written salary bill only','a cloud passing overhead','Stone can be carved into a sculpture.','context'),Q(1,'Which phrase is natural?','sculpt a figure from clay','sculpt at a figure by claying','sculpting a figure to from','From introduces the material shaped.','grammar'),Q(1,'Sculpt derives from Latin sculpere, meaning…','carve','sail','season food','The Latin verb means carve or engrave.','word-formation')]);
P('sculptor','From Latin sculptor, from sculpere “carve”; a sculptor makes art by carving or modelling solid material, or figuratively shapes an institution or character.',[C('sculptor.s1','艺术','The sculptor carved the memorial figure from a block of marble.','雕塑家用一块大理石雕出了纪念像。','a sculptor in + material; sculptor of + work','名词，指用石、木、金属等立体材料创作的人。','artist carves marble.','艺术'),C('sculptor.s2','比喻','She was a sculptor of the new school system, shaping its curriculum and culture.','她塑造了新学校体系，设计课程并形成其文化。','a sculptor of + institution/character','比喻指塑造某个机构、制度或他人品格的人。','leader shapes institution.','比喻')],M('The sculptor of the marble statue never shaped or carved any material and only sold tickets.','The sculptor carved and shaped the marble into a statue.','不参与塑形或雕刻的人不是该作品的雕塑家。','meaning'),[Q(1,'A sculptor working in marble…','carves or models the stone into art','sells the stone without shaping it','writes a script about a sea lion','Sculptors make three-dimensional works.','meaning'),Q(2,'Calling a reformer a sculptor of a school system means the reformer…','shaped its structure and culture','made a statue from school desks','worked as a seafarer','This is the figurative sense of shaping an institution.','context'),Q(1,'Which phrase is natural?','a sculptor of the memorial','a sculptor to memorialing of','a sculptorly memorial','Of introduces the work or institution shaped.','grammar'),Q(1,'Sculptor is related to Latin sculpere, “to…”','carve','scramble','screen','The word comes from the Latin carving family.','word-formation')]);
P('sculptural','Sculptural is formed from sculpture + -al; it means related to sculpture or having a strongly three-dimensional, sculpted form.',C('sculptural.s1','建筑','The building’s sculptural staircase curves upward like a ribbon of stone.','建筑里雕塑般的楼梯向上盘旋，宛如一条石带。','sculptural form/quality/design','形容词，指与雕塑有关或具有突出的立体造型。','staircase has three-dimensional shape.','建筑'),M('The designer called the sculptural staircase flat and shapeless, with no three-dimensional form.','The designer called the staircase sculptural because its three-dimensional curves resembled a carved artwork.','立体曲线造型与“平坦无形”相矛盾。','meaning'),[Q(1,'A sculptural staircase is…','shaped in a striking three-dimensional way','a written script for a play','a ladder covered in salt','Sculptural describes a form resembling sculpture.','meaning'),Q(1,'Which object is most likely sculptural?','a building with dramatic curved forms','a perfectly flat sheet of paper','a simple list of ticket prices','Pronounced three-dimensional form can be sculptural.','context'),Q(1,'Which phrase is natural?','a sculptural design','a sculptural of designly','a sculpture designly form','Sculptural is an adjective modifying design.','grammar'),Q(1,'Sculptural is formed from sculpture plus…','-al','-er','-ness','The suffix -al forms an adjective meaning related to sculpture.','word-formation')]);
P('sculpture','From Latin sculptura “carving,” from sculpere; sculpture is the art of carving or shaping material, or an object produced by that art.',[C('sculpture.s1','艺术','She studied sculpture and learned to work with clay, wood, and bronze.','她学习雕塑，掌握了使用黏土、木材和青铜创作的方法。','study/practice sculpture; sculpture in + material','名词，指雕刻或塑形立体艺术的创作活动。','student studies art form.','艺术'),C('sculpture.s2','艺术','A marble sculpture of a seated figure stands in the museum entrance.','一尊坐姿人物的大理石雕像立在博物馆入口处。','a sculpture of + subject; a stone sculpture','名词也指用这种艺术制作的具体物件。','finished statue on display.','艺术')],M('The museum displayed a sculpture, but it was an empty patch of wall with no carved or shaped object.','The museum displayed a sculpture, a three-dimensional object carved from stone.','具体雕塑是制作出的物件，不是空墙面。','meaning'),[Q(1,'Sculpture as an art form involves…','carving or shaping material into figures','writing a screenplay','screening people for illness','Sculpture is the art of making shaped three-dimensional works.','meaning'),Q(2,'A sculpture of a seated figure is…','an object made by sculpting','a rule against fraud','a tool for tightening screws','Sense 2 names the finished work.','context'),Q(1,'Which phrase is natural?','a sculpture of a horse','a sculpture to horseing of','sculpturely horse object','Of introduces the subject represented.','grammar'),Q(1,'Sculpture comes from Latin sculptura, meaning…','carving','a small sharp stone','a written scroll','The Latin source means carving or sculpture.','word-formation')]);
P('scum','From Old Norse skum “foam,” related to Germanic words for froth; scum is impure foam on liquid, and an insulting term for despicable people.',[C('scum.s1','环境','A grey scum formed on the stagnant pond after the hot week.','炎热的一周过后，死水池塘表面形成了一层灰色浮沫。','scum on + liquid; a layer of scum','名词，指液体表面不洁的泡沫；也可作侮辱性称呼。','impure film floats on pond.','环境')],M('A clean pond had a layer of scum on its surface even though the water was perfectly clear and free of foam.','A polluted pond had a layer of scum floating on its surface.','完全清澈无泡沫的水面没有scum。','meaning'),[Q(1,'Scum on a pond is…','impure foam floating on the liquid','a clean layer of drinking water','a seabird colony','Scum can mean dirty foam on a liquid.','meaning'),Q(1,'Calling a person scum is…','an insulting way to call them despicable','a formal title for a sculptor','a compliment for a careful scribe','The word also has a strongly contemptuous personal use.','usage'),Q(1,'Which phrase is natural?','scum on the surface of the pond','scum to surface pondly','pond scummed on the of','On identifies where the floating layer lies.','grammar'),Q(1,'The older word behind scum is associated with…','foam','a holy text','a salary','Scum traces to a Norse word for foam.','word-formation')]);
P('scurry','Scurry is an expressive verb of uncertain deeper origin; it describes hurrying with quick, short steps, often like a small animal.',C('scurry.s1','动作','The mice scurried under the cabinet when the kitchen light came on.','厨房灯亮起时，老鼠们小步飞快地钻到橱柜下面。','scurry away/off/to + place','动词，指以短促快速的步子急忙移动。','small animals hurry for cover.','动作'),M('The mice scurried across the room by taking slow, measured steps and stopping after each one.','The mice scurried across the room in quick, short steps.','缓慢且有停顿的步伐与scurry的急促动作相反。','meaning'),[Q(1,'Mice that scurry for cover…','hurry with quick, short steps','walk slowly in a straight line','scrutinize their food','Scurry describes hurried small steps.','meaning'),Q(1,'Which scene best fits scurry?','A child hurries across the hall with short quick steps.','A boat lies anchored at sea.','A sculptor studies a statue.','Quick, short movement is characteristic of scurrying.','context'),Q(1,'Which phrase is natural?','scurry away from danger','scurry danger to awayly','scurry on a sculpture into','Away from marks the direction of escape.','grammar'),Q(1,'The word scurry is…','an expressive verb with an uncertain deeper origin','an acronym for underwater gear','a formal term for a ballot counter','Its exact earlier formation is not confidently established.','word-formation')]);
P('scurviness','Scurviness is formed from scurvy + -ness; the archaic adjective scurvy developed a figurative sense of being vile or discourteous.',C('scurviness.s1','书面','The scurviness of the forged rumour shocked even the rival campaign staff.','那条伪造谣言的卑劣程度让对手阵营的工作人员也感到震惊。','the scurviness of + act/person','名词，指卑鄙、可鄙或粗鲁无礼的性质。','rumour is despicable.','书面'),M('The scurviness of her generous apology showed how courteous and admirable the act was.','The scurviness of the insult showed how vile and discourteous the act was.','慷慨道歉、彬彬有礼与scurvy所指卑劣相反。','meaning'),[Q(1,'Scurviness is…','the quality of being vile or discourteous','the state of being salty','the ability to sculpt stone','The noun names the despicable quality.','meaning'),Q(1,'A malicious fabricated rumour could show…','scurviness','seasonality','seagoing','The cruel and low act is scurvy in character.','context'),Q(1,'Which phrase is natural?','the scurviness of the attack','the scurviness to attacking by','scurvyly of the attackness','Of introduces the act displaying the quality.','grammar'),Q(1,'Scurviness is formed from scurvy plus…','-ness','-er','-ful','The suffix -ness forms a noun naming a quality.','word-formation')]);
P('scuttle','Scuttle’s two verb senses have separate histories: the “hurry off” sense is related to scud, while the ship-sinking sense refers to opening a vessel’s hull; the deeper origins are uncertain.',[C('scuttle.s1','动作','The minister scuttled out of the room before reporters could ask questions.','记者还没来得及提问，部长就匆匆溜出了房间。','scuttle off/out/away','动词，指迅速离开，常带慌忙意味。','person hurries away.','动作'),C('scuttle.s1','航海','The captain ordered the crew to scuttle the damaged vessel rather than let it drift into the harbour.','船长命令船员凿沉受损船只，以免它漂进港口。','scuttle a ship/vessel','航海动词，指在船壳开孔使船沉没。','hull opened deliberately.','航海')],M('The crew scuttled the damaged ship by sealing every opening and keeping it afloat.','The crew scuttled the damaged ship by opening its hull and letting it sink.','封闭船体并使其漂浮与凿沉相反。','meaning'),[Q(1,'He scuttled out of the room means he…','hurried away','stood still and waited','sealed the room permanently','This sense means leave quickly.','meaning'),Q(1,'To scuttle a ship is to…','make it sink by opening its hull','repair its hull and keep it afloat','write its seagoing script','The nautical sense means deliberately sink a vessel.','context'),Q(1,'Which phrase is natural?','scuttle away before dawn','scuttle before dawn awayly','scuttle to away the dawn','Scuttle away is a natural phrasal construction.','grammar'),Q(1,'Scuttle has…','two verb senses with distinct histories','only one spelling variant','a single meaning of “seal tightly”','The entry distinguishes hurrying off from sinking a ship.','distinction')]);
P('sea','From Old English sæ, a Germanic word; sea is a large area of salt water or, figuratively, a very large number or amount.',[C('sea.s1','地理','The fishing village sits beside the sea, where the cliffs meet the water.','这个渔村坐落在海边，那里悬崖与海水相接。','by/at/into the sea; sea water','名词，指覆盖地球大片区域的咸水。','coastal village by salt water.','地理'),C('sea.s2','比喻','A sea of faces filled the square during the concert.','音乐会期间，广场上挤满了人，宛如一片人海。','a sea of + plural noun','比喻指某物数量极大、铺展开来。','crowd fills square.','比喻')],M('They spent the day beside the sea, a dry mountain desert with no salt water.','They spent the day beside the sea, the large area of salt water beyond the shore.','sea指咸水海域，不是无水沙漠。','meaning'),[Q(1,'The sea is…','a large area of salt water','a layer of dry scrubland','a handwritten script','Sea sense 1 names a large body of salt water.','meaning'),Q(2,'A sea of faces means…','a very large crowd of people','a group of fish in one small net','a quiet empty square','The figurative sense means a vast number or amount.','context'),Q(1,'Which phrase is natural?','by the sea','by seaing the','at the sea of to','By the sea means beside the coast.','grammar'),Q(2,'Which sentence uses sea figuratively?','A sea of paperwork covered the desk.','They sailed across the sea.','The seabed lies below the water.','A great quantity of paperwork is described as a sea.','meaning')]);
P('sea lion','Sea lion is a compound common name for a large marine mammal with flat flippers and a lion-like body shape.',C('sea lion.s1','动物','A sea lion balanced a ball on its nose during the aquarium show.','水族馆表演中，一头海狮把球顶在鼻子上保持平衡。','a sea lion colony; sea lions rest on rocks','名词，指有扁平鳍状肢、体形似狮子的大型海洋动物。','marine mammal performs.','动物'),M('The sea lion swam with feathers and a beak because it was a coastal bird.','The sea lion swam with flippers because it is a marine mammal.','海狮是哺乳动物，不是有羽毛和喙的鸟。','distinction'),[Q(1,'A sea lion is…','a large marine mammal with flippers','a fish that grows on the seabed','a land plant','Sea lions are marine mammals.','meaning'),Q(1,'A sea lion might balance a ball with…','its nose','a sail','a screwdriver','The source example describes the animal balancing a ball on its nose.','context'),Q(1,'Which phrase is natural?','a sea lion colony','a sea lioning colony','a lion sea to colony','Sea lion is a two-word animal name.','grammar'),Q(1,'The name sea lion refers to the animal’s…','marine habitat and lion-like body shape','ability to write a script','seasonal migration into forests','The compound combines sea with a lion-like appearance.','word-formation')]);
P('seabed','Seabed combines sea and bed; it means the solid ground at the bottom of a sea or ocean.',C('seabed.s1','海洋','The survey team buried the cable in the seabed to protect it from anchors.','勘测队把电缆埋进海床，以免被船锚破坏。','on/under/beneath the seabed','名词，指海洋底部的地面。','cable placed below water.','海洋'),M('The cable was buried in the seabed, the moving surface of the waves above the ocean.','The cable was buried in the seabed, the solid ground beneath the water.','seabed指海底地面，不是水面波浪。','meaning'),[Q(1,'The seabed is…','the ground beneath the sea','the top surface of a wave','the deck of a ship','Seabed names the bottom of the sea.','meaning'),Q(1,'An underwater cable may be buried in the seabed to…','protect it from anchors and damage','make it visible above the waves','turn it into seafood','The sea bottom can shelter cables.','context'),Q(1,'Which phrase is natural?','map the seabed','map seabedly of','sea the bed map to','Surveyors map the seabed.','collocation'),Q(1,'Seabed combines sea with…','bed','board','bird','The compound names the sea’s bottom surface.','word-formation')]);
P('seabird','Seabird combines sea and bird; it is a bird that lives near the sea and obtains food from the marine environment.',C('seabird.s1','动物','Seabirds nested on the cliffs and fed on small fish from the bay.','海鸟在悬崖上筑巢，以海湾里的小鱼为食。','seabird colony/nest; seabirds feed on + fish','名词，指生活在海边并从海中觅食的鸟。','coastal birds catch fish.','动物'),M('The seabirds nested in the desert and fed only on inland wheat, far from any marine habitat.','The seabirds nested on coastal cliffs and fed on fish from the sea.','远离海边且不从海中觅食与seabird的定义相反。','distinction'),[Q(1,'A seabird typically…','lives near the sea and gets food from it','lives only in dry underground caves','is a sea mammal with flippers','Seabirds are birds adapted to coastal or marine life.','meaning'),Q(1,'A colony of seabirds on a cliff might feed on…','fish from nearby water','screwdrivers','saffron threads','Their food comes from the sea.','context'),Q(1,'Which phrase is natural?','a seabird colony','a seabird of colonying','colony seabirds to a','A group of nesting birds is a seabird colony.','collocation'),Q(1,'Seabird is formed from…','sea + bird','seal + board','season + bird','The compound directly names a bird associated with the sea.','word-formation')]);
P('seaboard','Seaboard combines sea and board, where board means a border or side; it names a coastal region, often described as eastern or western.',C('seaboard.s1','地理','Ports along the Atlantic seaboard shipped grain to overseas markets.','大西洋沿岸地区的港口把谷物运往海外市场。','the eastern/western/Atlantic seaboard','名词，指国家或地区濒临海洋的沿海地带。','ports along coast.','地理'),M('The western seaboard was hundreds of miles inland and had no coast or access to the sea.','The western seaboard stretched along the coast facing the Pacific.','seaboard是临海地区，不是远离海岸的内陆。','meaning'),[Q(1,'A country’s seaboard is…','the region bordering the sea','its highest mountain range inland','a strip of seabed','Seaboard names a coastal region.','meaning'),Q(1,'The Atlantic seaboard would include…','coastal areas facing the Atlantic Ocean','farmland in the centre of a continent','a ship’s dining room','The phrase refers to areas along the Atlantic coast.','context'),Q(1,'Which phrase is natural?','the eastern seaboard','the seaboard of eastly','the eastern seabed board','Eastern seaboard is a common regional phrase.','collocation'),Q(1,'In seaboard, board contributes the idea of…','a side or border','a sea animal','a writing script','Here board means a side or bordering region.','word-formation')]);
P('seacoast','Seacoast combines sea and coast; it means the part of land that meets the sea.',C('seacoast.s1','地理','Storm waves have eroded the seacoast along this headland for decades.','数十年来，风暴海浪一直侵蚀着这片岬角的海岸。','along/on the seacoast; seacoast erosion','名词，指陆地与海洋接壤的地带。','land edge meets ocean.','地理'),M('The map marked the seacoast in the middle of the continent, far from any sea.','The map marked the seacoast where the land meets the sea.','远离海洋的内陆不是seacoast。','meaning'),[Q(1,'The seacoast is…','the part of land that meets the sea','the deepest point beneath the sea','a ship’s writing room','Seacoast means the coastal edge.','meaning'),Q(1,'A storm may cause erosion along the…','seacoast','seabed only','scriptwriter','Waves wear away land where sea meets coast.','context'),Q(1,'Which phrase is natural?','protect the seacoast from erosion','protect seacoast to eroding of','seacoast protect an erosion','From introduces the threat being prevented.','grammar'),Q(1,'Seacoast combines sea and…','coast','scum','screw','The compound names the coast beside the sea.','word-formation')]);
P('seafarer','Seafarer combines sea, fare “travel,” and -er; it means someone who regularly works or travels at sea.',C('seafarer.s1','航海','Early seafarers navigated by the stars when the coastline disappeared from view.','早期航海者在看不见海岸线时靠星星导航。','an experienced seafarer; life of a seafarer','名词，指经常在海上工作或航行的人。','voyager uses stars.','航海'),M('The seafarer never traveled or worked at sea and spent every voyage in an inland desert.','The seafarer regularly worked aboard vessels traveling at sea.','从不出海的人不符合seafarer的定义。','meaning'),[Q(1,'A seafarer is someone who…','works or voyages regularly on the sea','works only in an inland bakery','writes sea-themed screenplays only','Seafarer means a person who travels or works at sea.','meaning'),Q(1,'Early seafarers used stars to…','navigate when they could not see the coast','measure a salary bill','scrape paint off a ship','Celestial navigation helped sailors find their way.','context'),Q(1,'Which phrase is natural?','an experienced seafarer','an experience seafarerly','a seafarer of experiencing to','Experienced modifies the person’s sea-travel history.','grammar'),Q(1,'The word seafarer includes fare in the sense…','travel','season food','write','Fare can mean travel, as in seafaring.','word-formation')]);
P('seafloor','Seafloor combines sea and floor; it means the ground beneath seawater, also called the ocean floor.',C('seafloor.s1','地理','Researchers mapped the seafloor to locate ridges and underwater volcanoes.','研究人员绘制了海底地图，以寻找海脊和海底火山。','the ocean/seafloor; seafloor mapping','名词，指海水之下的地面。','mapping underwater ground.','地理'),M('The seafloor is the dry upper surface of the sea waves, not the ground beneath them.','The seafloor is the ground lying beneath the seawater.','海床/海底不等于水面。','distinction'),[Q(1,'The seafloor is…','the ground beneath ocean water','the top surface of a wave','the bottom of a boat','Seafloor means the submerged ground.','meaning'),Q(1,'A survey of seafloor ridges studies…','underwater geological features','the clothes on a fashion runway','the pages of a screenplay','Ridges and volcanoes can occur on the ocean floor.','context'),Q(1,'Which phrase is natural?','map the seafloor','map the seaflooring to','sea the floor underly map','Seafloor mapping is a standard activity.','collocation'),Q(1,'Seafloor is a compound of sea and…','floor','fare','food','The compound identifies the floor beneath the sea.','word-formation')]);
P('seafood','Seafood combines sea and food; it means fish and shellfish from the sea that people eat.',C('seafood.s1','饮食','The harbour restaurant serves seafood caught by local boats that morning.','港口餐厅供应当天早晨由当地船只捕获的海鲜。','fresh seafood; seafood restaurant','名词总称可食用的海鱼和贝类。','fish and shellfish served.','饮食'),M('The restaurant advertised seafood but served only land-grown wheat and apples.','The restaurant served fish and shellfish caught from the sea.','小麦和苹果不是海产品。','meaning'),[Q(1,'Seafood includes…','fish and shellfish from the sea','only land-grown vegetables','tools used by sailors','Seafood is food from marine animals.','meaning'),Q(1,'A seafood restaurant is likely to serve…','fish caught by local boats','scriptwriting services','fresh paint scrapers','Fish is a typical seafood item.','context'),Q(1,'Which phrase is natural?','fresh seafood','freshly seafooding','seafood of fresh to','Fresh commonly modifies seafood.','grammar'),Q(1,'Seafood combines sea with…','food','floor','board','It names food obtained from the sea.','word-formation')]);
P('seagoing','Seagoing combines sea and going; it describes vessels designed to travel on the open ocean rather than only sheltered waters.',C('seagoing.s1','航海','The port inspects every seagoing vessel before it leaves the harbour for open water.','港口会在船只驶向外海前检查每一艘远洋船舶。','a seagoing ship/vessel','形容词，指适合在海洋航行的船只。','vessel built for open ocean.','航海'),M('The seagoing vessel was designed only for a shallow pond and could not leave the sheltered lake.','The seagoing vessel was built to travel on the open ocean.','仅适合浅水池的船不适合远洋航行。','meaning'),[Q(1,'A seagoing vessel is designed to…','travel on the open sea','operate only in a swimming pool','stay permanently on dry land','Seagoing means suitable for sea travel.','meaning'),Q(1,'Which boat is most clearly seagoing?','A ship licensed for long ocean voyages','A small craft for a sheltered garden pond','A sculpture displayed indoors','Open-ocean design defines seagoing.','context'),Q(1,'Which phrase is natural?','a seagoing ship','a sea-goingly ship','a ship seagoingness','Seagoing is an adjective before ship.','grammar'),Q(1,'Seagoing combines sea with the -ing form of…','go','scrape','seal','Going contributes the idea of traveling on the sea.','word-formation')]);
P('seagull','Seagull combines sea and gull; it commonly names a loud-crying coastal bird that eats fish or scraps, and may refer broadly to gull-like seabirds.',[C('seagull.s1','动物','Seagulls followed the fishing boat, waiting for scraps from the deck.','海鸥跟着渔船飞，等着吃甲板上丢下的残食。','a flock of seagulls; seagulls follow boats','名词，指常见于海岸、捕食鱼类或残食的鸥鸟。','birds trail fishing boat.','动物'),C('seagull.s2','动物','Several kinds of seagull nested on the cliffs above the bay.','海湾上方的悬崖上有好几种鸥类海鸟筑巢。','kinds/species of seagull','也可泛指鸥类海鸟，并非单一物种。','multiple gull species.','动物')],M('The seagulls followed the boat, but they were silent mammals with flippers and no wings.','The seagulls followed the boat, calling loudly as they searched for fish and scraps.','海鸥是有翅膀的鸟，不是无声的鳍足类哺乳动物。','distinction'),[Q(1,'A seagull is a coastal…','bird that may eat fish or scraps','mammal with flat flippers','sea plant','Seagulls are gull-like birds.','meaning'),Q(2,'“Several kinds of seagull” means…','more than one kind of gull-like seabird','one individual sea lion','a school of fish only','The broader sense includes multiple gull species.','context'),Q(1,'Which phrase is natural?','a flock of seagulls','a flock of seagullings','a seagull to a flock at','A group of birds is a flock.','collocation'),Q(1,'Seagull combines sea and…','gull','seal','sail','The second part identifies the bird family.','word-formation')]);
P('seal','The marine-animal sense comes from Old English seolh; the official-mark sense came through Old French seel from Latin sigillum, and the verb developed from the idea of closing with a seal.',[C('seal.s1','动物','Seals rested on the rocks between feeding trips in the cold water.','海豹在冰冷海水中觅食的间隙，躺在岩石上休息。','a seal colony; seals rest/breed on land','名词，指有鳍状肢、吃鱼并在陆地繁殖的海洋动物。','animals lie on rocks.','动物'),C('seal.s2','历史','The letter bore the royal seal in red wax beneath the signature.','信件签名下方盖有红蜡制成的王室印章。','an official/royal seal; bear a seal','名词，指显示正式或未拆封的蜡印或印记。','wax mark authenticates letter.','历史'),C('seal.s3','家居','Seal the jar tightly so that air cannot reach the preserves.','把罐子密封好，别让空气接触里面的腌渍食品。','seal a container/envelope; seal something tightly','动词，指封严以防空气或液体进出。','jar closed against air.','家居'),C('seal.s4','商业','The last-minute goal sealed the team’s victory.','最后时刻的进球锁定了球队的胜利。','seal a deal/victory/fate','动词也可表示使结果确定下来。','goal makes win certain.','商业')],M('She sealed the jar tightly, leaving its lid open so air could enter freely.','She sealed the jar tightly by closing its lid so air could not enter.','盖子敞开不能密封容器。','meaning'),[Q(1,'A seal resting on a rock is…','a marine mammal with flippers','a wax stamp on a letter','a screw-fastening tool','Seal sense 1 is the animal.','meaning'),Q(2,'A royal seal on a letter is…','an official mark made in wax or another material','a sea animal that eats fish','a film shown on a screen','The noun sense identifies an official or unopened mark.','context'),Q(3,'To seal a jar is to…','close it so air or liquid cannot pass','leave the lid open','make a victory certain','Seal sense 3 means close tightly.','meaning'),Q(4,'A goal sealed the victory means it…','made the result certain','closed a jar of food','made the team lose','This figurative sense fixes the outcome.','meaning')]);
P('sealed','Sealed is the past participle of seal; as an adjective it means closed tightly so that air or liquid cannot pass in or out.',C('sealed.s1','家居','The laboratory stored the samples in sealed jars to prevent contamination.','实验室把样本存放在密封罐里，以防污染。','a sealed jar/envelope/container; keep something sealed','形容词，表示已封严、空气或液体无法进出的状态。','container prevents entry.','家居'),M('The sealed sample jar had its lid off and remained open to the air.','The sealed sample jar had its lid firmly closed against the air.','开盖暴露在空气中不属于sealed状态。','meaning'),[Q(1,'A sealed jar is…','closed tightly against air or liquid','left open on a table','covered with a screenplay','Sealed means tightly closed.','meaning'),Q(1,'Why put samples in sealed containers?','To prevent outside contamination from entering.','To let air freely enter.','To make them into sculptures.','A tight seal blocks unwanted material.','context'),Q(1,'Which phrase is natural?','a sealed envelope','a sealing envelope of','an envelope sealedly','Sealed can modify a tightly closed envelope.','grammar'),Q(1,'Sealed is the past participle of…','seal','sea','scud','The adjective comes from the verb seal.','word-formation')]);
P('sealer','Sealer is formed from seal + -er; it is a coating used to close pores or gaps and keep air or liquid from passing through.',C('sealer.s1','装修','Apply a wood sealer before painting the bare floorboards.','给裸露的地板涂漆前，先刷一层木材封闭剂。','wood/concrete sealer; apply a sealer to + surface','名词，指封闭孔隙或缝隙、阻止渗透的涂料。','coating fills pores.','装修'),M('The carpenter used a sealer that opened every pore in the wood and let water pass through.','The carpenter used a sealer that closed the wood’s pores and resisted water.','封闭剂的作用是封住孔隙，不是让水渗入。','meaning'),[Q(1,'A wood sealer is…','a coating that closes pores and gaps','a sea mammal','a tool used to write scripture','A sealer prevents air or liquid from passing through a surface.','meaning'),Q(1,'Why apply sealer before painting bare wood?','It closes pores in the surface.','It makes every gap larger.','It scrapes the paint off.','Sealer prepares and protects a porous surface.','context'),Q(1,'Which phrase is natural?','apply a sealer to the wood','apply a sealer from wooding to','sealer the wood with apply','To introduces the surface treated.','grammar'),Q(1,'Sealer is formed from seal plus…','-er','-less','-ity','The suffix -er can name an agent or material that seals.','word-formation')]);
P('seam','From Old English seam, a Germanic word for a joined edge; seam is a stitched line between pieces or a thin underground layer of coal, stone, or ore.',[C('seam.s1','服装','The seam along the jacket sleeve came apart after several washes.','夹克袖子上的接缝洗了几次后开裂了。','a seam in/on + garment; sew a seam','名词，指缝合布料或材料后形成的线。','stitches join fabric edges.','服装'),C('seam.s2','地质','The miners followed a thin coal seam deep into the hillside.','矿工沿着山坡深处的一层薄煤层开采。','a coal/ore seam; a seam of + material','也指地下长条状分布的一层矿石或岩石。','coal layer underground.','地质')],M('The miners found a coal seam, a line of stitching joining two pieces of cloth underground.','The miners found a coal seam, a long thin layer of coal in the rock.','地质义seam是矿层，不是缝衣线。','distinction'),[Q(1,'The seam on a jacket is…','the stitched line joining pieces of fabric','the jacket’s metal screw','a patch of salt water','Seam sense 1 is a sewn join.','meaning'),Q(2,'A coal seam is…','a thin underground layer of coal','a seamstress’s thread only','an ocean route','Seam sense 2 is a geological layer.','context'),Q(1,'Which phrase is natural?','a seam in the sleeve','a seam to the sleeve from','a seamed of sleeve at','A seam may run along or in a garment.','grammar'),Q(2,'Which worker might search for a seam underground?','a miner looking for coal','a tailor fitting a jacket','a scriptwriter','Coal seams are geological deposits.','meaning')]);
P('seaman','Seaman combines sea and man; it means a member of a ship’s crew trained in seamanship, including a sailor or naval rating.',C('seaman.s1','航海','The seaman had spent twenty years in the merchant fleet before retiring.','这名水手在商船队工作了二十年后退休。','a merchant/naval seaman; a seaman aboard a ship','名词，指受过航海训练的船员。','crew member at sea.','航海'),M('The seaman had never served aboard a vessel and worked only as a landlocked mountain farmer.','The seaman was a trained member of the ship’s crew.','从未上船工作的内陆农夫不是水手。','meaning'),[Q(1,'A seaman is…','a trained member of a ship’s crew','a person who sells seaweed','a type of underwater mountain','Seaman means a shipboard crew member.','meaning'),Q(1,'A merchant-fleet seaman works…','on commercial vessels at sea','only in a salon','on a desert farm','Merchant ships employ seamen.','context'),Q(1,'Which phrase is natural?','a seaman aboard the vessel','a seaman to vessel aboard of','seaman the vessel aboarded','Aboard locates the worker on the ship.','grammar'),Q(1,'Seaman combines sea and…','man','mount','scum','The compound names a man serving at sea.','word-formation')]);
P('seamount','Seamount combines sea and mount; it is an underwater mountain whose peak remains below sea level.',C('seamount.s1','海洋','The sonar survey mapped a seamount rising from the ocean floor but not reaching the surface.','声呐勘测绘制了一座从海底隆起、但没有露出海面的海山。','an underwater seamount; seamount rises from the seabed','名词，指海底山峰，峰顶仍在海平面以下。','mountain remains submerged.','海洋'),M('The seamount rose above the water as a dry mountain island with its peak in the sky.','The seamount rose from the ocean floor but remained submerged below sea level.','峰顶露出海面的山不符合seamount定义。','distinction'),[Q(1,'A seamount is…','a mountain on the seabed with its peak below sea level','a coastal mountain visible above the sea','a mound of food on a plate','A seamount is an underwater mountain.','meaning'),Q(1,'Sonar can help researchers…','map a submerged seamount','read a seafarer’s handwritten script','apply a wood sealer','Sonar maps underwater landforms.','context'),Q(1,'Which phrase is natural?','a seamount rises from the seabed','a seamount floats on the sky','seamounting at the coast','A seamount rises from the ocean floor.','grammar'),Q(1,'Seamount combines sea with…','mount','man','meal','Mount contributes the idea of a mountain.','word-formation')]);
P('seaport','Seaport combines sea and port; it names a coastal town or district where ships load and unload goods and passengers.',C('seaport.s1','交通','The old seaport expanded its docks to handle larger container ships.','这座古老海港扩建了码头，以接纳更大的集装箱船。','a busy/major seaport; seaport facilities','名词，指海岸上供船舶装卸货物和旅客的城镇或区域。','docks serve ships.','交通'),M('The seaport lay far inland with no coast, docks, or access for ships.','The seaport developed on the coast around docks where ships could load and unload.','没有海岸和船舶设施的内陆城市不是海港。','meaning'),[Q(1,'A seaport is…','a coastal place where ships load and unload','a mountain beneath the sea','an inland airport runway','A seaport serves ships and passengers at the coast.','meaning'),Q(1,'A container ship entering a seaport may…','unload cargo at the docks','scuttle a screenplay','season the seabed','Ports handle loading and unloading.','context'),Q(1,'Which phrase is natural?','a busy seaport','a busy seaporting of','a port of sea busyly','Busy can modify seaport.','grammar'),Q(1,'Seaport combines sea with…','port','shore','sear','Port is the harbor or shipping facility.','word-formation')]);
P('seaquake','Seaquake combines sea and quake; it is a sudden earthquake beneath the ocean that can generate a tsunami.',C('seaquake.s1','地质','A seaquake shook the research vessel far offshore and triggered a tsunami warning.','远海的一次海底地震震动了科考船，并触发海啸预警。','an undersea quake/seaquake; a seaquake triggers + tsunami','名词，指发生在海底的地震。','seismic shaking under ocean.','地质'),M('The seaquake occurred beneath a mountain on dry land, miles from any ocean.','The seaquake occurred beneath the ocean floor offshore.','海底地震发生在海洋之下，不是远离海洋的陆地山中。','meaning'),[Q(1,'A seaquake is…','an earthquake beneath the ocean','a storm above a seaport','a quake caused by a screenplay','The compound names underwater seismic shaking.','meaning'),Q(1,'Why might a seaquake prompt a tsunami warning?','Undersea shaking can displace water.','It always dries out the ocean.','It seals the coast against waves.','A seafloor quake may generate a tsunami.','context'),Q(1,'Which phrase is natural?','a seaquake shook the vessel','a seaquake seasonally the vessel','a vessel seaquake into','A seaquake can shake a vessel offshore.','grammar'),Q(1,'Seaquake combines sea with…','quake','quail','sealer','Quake names the sudden shaking.','word-formation')]);
P('sear','Sear is an old English verb of Germanic origin; it means scorch the outside of meat or tissue with intense heat.',C('sear.s1','烹饪','Sear the tuna quickly on both sides so the centre stays rare.','把金枪鱼两面快速煎焦，这样中间仍保持嫩生。','sear meat on both sides; sear over high heat','及物动词，指用强热灼烤食物或组织表面。','surface browned by heat.','烹饪'),M('The chef seared the tuna by chilling it until its outside remained raw and cold.','The chef seared the tuna briefly in a hot pan to brown the outside.','低温冷却不会把表面灼烤焦香。','meaning'),[Q(1,'To sear a steak is to…','scorch its outside with high heat','freeze it until it is solid','scrutinize it closely','Sear describes intense heat applied to the surface.','meaning'),Q(1,'Why sear tuna briefly?','To brown the outside while keeping the centre rare.','To boil it until every part is dry.','To seal it in a paper scroll.','A quick high-heat sear cooks the surface.','context'),Q(1,'Which phrase is natural?','sear the meat over high heat','sear the meat under cold water','sear to meat by highing','Over high heat describes the cooking condition.','grammar'),Q(1,'Sear is closest in meaning to…','scorch the surface','grow seasonally','move text on a screen','Sear means burn or brown the outside with heat.','meaning')]);
P('search','From Old French cerchier “search, seek,” related to Latin circuire “go around”; search means look carefully for something or information, or the act of doing so.',[C('search.s1','通用','Coastguards searched the cliffs for the missing child.','海岸警卫队在悬崖一带寻找失踪的孩子。','search for + person/object; search a place','动词，指在地点仔细寻找人或物。','rescue team looks carefully.','通用'),C('search.s2','科技','Search the web for the report’s title to find the publisher’s archive.','在网上搜索报告标题，就能找到出版方的档案。','search the web/database for + term','动词，指在电脑或互联网上查找信息。','online query finds archive.','科技'),C('search.s3','通用','The search for the lost hiker continued until dawn.','寻找失踪徒步者的行动一直持续到黎明。','a search for + person/thing; conduct a search','名词，指仔细寻找的行动。','effort lasts overnight.','通用')],M('They searched the cliffs for the child by refusing to look anywhere along the cliffs.','They searched the cliffs for the child by checking each path and ledge.','不查看目标区域不能算在该区域仔细寻找。','meaning'),[Q(1,'Coastguards search the cliffs for a missing child by…','looking carefully in the area','screening a film there','seasoning the rocks','Search sense 1 means look carefully for someone or something.','meaning'),Q(2,'Search the web for a title means…','look online for information about it','look for a wet shell on the beach','seal a website shut','This is the information-finding sense.','context'),Q(3,'A search for the keys is…','an act of trying to find them','the keys themselves','a decision to cancel the trip','Search can be a noun naming the effort.','meaning'),Q(2,'Which phrase is natural?','search the database for the name','search for the database to the name','searching database forly name','For introduces the information being sought.','grammar')]);
P('seashell','Seashell combines sea and shell; it is a shell from a marine animal, especially one washed onto a beach.',C('seashell.s1','海岸','Children collected seashells that had washed up after the storm.','风暴过后，孩子们捡起了被冲上岸的海贝壳。','collect/find a seashell; seashells wash up','名词，指海洋动物的硬壳，尤指被海浪冲上岸的壳。','shells found on beach.','海岸'),M('The child found a seashell, a living fish with fins still swimming in the waves.','The child found a seashell, the empty hard shell of a marine animal washed onto shore.','贝壳是硬壳，不是活鱼本身。','distinction'),[Q(1,'A seashell is…','a hard shell from a marine animal','a living sea lion','a piece of seaweed','The word names a shell from the sea.','meaning'),Q(1,'After a storm, a beachcomber might find…','seashells washed up on shore','a sealed jar buried in a sculpture','scraps of screenplay','Waves can wash shells onto the beach.','context'),Q(1,'Which phrase is natural?','collect seashells on the beach','collect seashellly on beaching','collect the sea from shells','People collect shells along the shore.','grammar'),Q(1,'Seashell combines sea with…','shell','shelf','seal','The compound specifies a shell from the sea.','word-formation')]);
P('seashore','Seashore combines sea and shore; it is the shoreline where land meets the sea, often including the area affected by tides.',C('seashore.s1','地理','Kelp lay in dark lines along the seashore after the storm.','风暴过后，海带沿着海岸堆成一道道深色线。','along/on the seashore; walk the seashore','名词，指海与陆地相接的岸边地带。','tide leaves seaweed on shore.','地理'),M('They walked along the seashore while remaining hundreds of miles inland and far from water.','They walked along the seashore where the land met the sea.','远离水域的内陆不是海岸。','meaning'),[Q(1,'The seashore is…','the land beside the sea','the floor below the sea','the inside of a salon','Seashore names the shore where land meets sea.','meaning'),Q(1,'After a storm, kelp may be found…','along the seashore','inside a sealed jar','on a mountain peak far inland','Seaweed can wash onto the shoreline.','context'),Q(1,'Which phrase is natural?','walk along the seashore','walk the seashore to along of','walk seashoring by','Along describes movement beside the shore.','grammar'),Q(1,'Seashore combines sea with…','shore','scrub','screw','Shore is the land at the water’s edge.','word-formation')]);
P('seaside','Seaside combines sea and side; as a noun it means the area beside the sea, especially a place people visit for leisure.',C('seaside.s1','旅行','We spent a quiet week at a seaside town in Devon.','我们在德文郡的一座海滨小镇度过了安静的一周。','at/by the seaside; a seaside resort/town','名词，指海边地区，尤指休闲度假地。','holiday by coast.','旅行'),M('They booked a seaside holiday in a town hundreds of miles from any coast.','They booked a seaside holiday in a coastal town beside the sea.','远离海岸的城镇不是seaside度假地。','meaning'),[Q(1,'A seaside resort is…','a leisure place beside the sea','a mountain mine','a scriptwriter’s desk','Seaside describes a coastal holiday area.','meaning'),Q(1,'Where might a family spend a seaside holiday?','in a coastal town','in an inland desert with no water','in a sealed container','A seaside visit is made by the sea.','context'),Q(1,'Which phrase is natural?','stay at the seaside','stay into seasideing','stay the seaside with to','At the seaside is a common phrase.','collocation'),Q(1,'Seaside combines sea with…','side','sail','season','The compound means the side or area by the sea.','word-formation')]);
P('season','From Old French saison, via Latin satio “sowing,” from serere “to sow”; season names a part of the year, a period for an activity, or the verb meaning add flavour.',[C('season.s1','时间','Winter is the season when the lake freezes over.','冬天是湖面结冰的季节。','in/during a season; the four seasons','名词，指春夏秋冬一年中的一个时期。','winter period.','时间'),C('season.s2','活动','Hotels are fully booked during the holiday season.','假日期间酒店全部订满。','the tourist/racing/holiday season','名词也指某种活动集中进行的一段时间。','tourists arrive in set period.','活动'),C('season.s3','烹饪','Season the soup with black pepper just before serving.','上桌前用黑胡椒给汤调味。','season food with + salt/spice','动词，指往食物中加入盐、胡椒或香料。','spice added to soup.','烹饪')],M('Season the soup with pepper by removing all spices and leaving it completely unflavoured.','Season the soup with pepper by adding the spice to improve its flavour.','season food是加调料，而非去除调味料。','meaning'),[Q(1,'Winter is a season meaning…','one of the four parts of the year','a sea route','a writing system','Season sense 1 names spring, summer, autumn, or winter.','meaning'),Q(2,'The holiday season is…','a period when holiday activity is common','a single day with no travel','a permanent employment salary','Sense 2 is a time associated with an activity.','context'),Q(3,'To season soup is to…','add salt, pepper, or spices','cool it until frozen','scrutinize it for a disease','Season as a verb means add flavouring.','meaning'),Q(3,'Which phrase is natural?','season the vegetables with herbs','season the vegetables by herbs to','seasoning the vegetables for with','With introduces the added flavouring.','grammar')]);
P('seasonable','Seasonable combines season and -able; it means normal or appropriate for a particular time of year, and can also mean opportune.',C('seasonable.s1','天气','Seasonable rain arrived just as the wheat began to head.','恰逢小麦抽穗时，降下了符合季节规律的雨水。','seasonable weather/rain; seasonable for + time','形容词，表示适合该季节的常态或及时合宜的。','rain arrives at useful seasonal time.','天气'),M('The farmers called the frost seasonable in midsummer, although it was completely out of place for that time of year.','The farmers called the spring rain seasonable because it was normal and useful for that time of year.','盛夏的霜冻并不符合当季常态。','distinction'),[Q(1,'Seasonable rain is rain that…','is normal or appropriate for that time of year','falls only inside a sealed jar','is always destructive','Seasonable means suitable for the season.','meaning'),Q(1,'A seasonable opportunity is…','timely and appropriate','available only under the sea','a tool for carving stone','The word can also mean opportune.','context'),Q(1,'Which phrase is natural?','seasonable weather','seasonable weatherly','seasonably weather','Seasonable is an adjective modifying weather.','grammar'),Q(1,'Seasonable is built from season plus…','-able','-ship','-er','The suffix forms an adjective meaning appropriate for a season.','word-formation')]);
P('seasonal','Seasonal is formed from season + -al; it describes something occurring only at a particular time of year or changing in a yearly cycle.',[C('seasonal.s1','工作','Fruit picking is seasonal work because the harvest lasts only a few months.','采摘水果属于季节性工作，因为收获期只有几个月。','seasonal work/job/product','形容词，表示只在一年中特定时期发生。','work tied to harvest.','工作'),C('seasonal.s2','商业','The hotel adjusts its prices to match the seasonal pattern in visitor numbers.','酒店根据游客人数的季节性变化调整价格。','seasonal pattern/change/fluctuation','也指随季节按规律变化的。','prices vary in annual cycle.','商业')],M('Fruit picking was called seasonal work even though the harvest and hiring continued unchanged every day of the year.','Fruit picking was seasonal work because hiring increased only during the harvest months.','全年不变的工作不具有季节性。','meaning'),[Q(1,'Seasonal work is work that…','happens only at a particular time of year','continues at the same level every day forever','is performed underwater','Seasonal means tied to a part of the year.','meaning'),Q(2,'Seasonal hotel prices…','change in a regular yearly pattern','never change during the year','are determined by a seamount','Sense 2 describes recurring yearly variation.','context'),Q(1,'Which phrase is natural?','seasonal employment','seasonally employment','seasonality employed','Seasonal is an adjective modifying employment.','grammar'),Q(1,'Seasonal is formed from season plus…','-al','-less','-ment','The suffix -al makes an adjective meaning related to a season.','word-formation')]);
P('seasonality','Seasonality is formed from seasonal + -ity; it names a regular pattern of change tied to particular times of the year.',C('seasonality.s1','商业','The hotel’s staffing plan accounts for the seasonality of beach tourism.','酒店的人员计划考虑了海滨旅游业的季节性变化。','the seasonality of + business/demand','名词，指随一年中时段规律起伏的模式。','tourism rises and falls by season.','商业'),M('The hotel’s seasonality meant that visitor numbers followed no pattern and stayed identical throughout the year.','The hotel’s seasonality meant that visitor numbers rose in summer and fell in winter.','seasonality指季节性规律，不是全年完全相同。','meaning'),[Q(1,'Seasonality in tourism means…','a regular pattern linked to different times of year','a one-time event with no recurring pattern','a policy that closes all hotels','Seasonality names recurring seasonal change.','meaning'),Q(1,'A beach hotel planning for seasonality might…','hire more staff during the busy summer months','use the same staffing every day despite demand','move its seaport inland','Seasonal demand changes staffing needs.','context'),Q(1,'Which phrase is natural?','the seasonality of demand','the seasonality demandly','the seasonality to demanding by','Of introduces the area showing seasonal variation.','grammar'),Q(1,'The suffix -ity in seasonality forms…','a noun naming a state or pattern','a person who sells rooms','a past-tense verb','Seasonality is an abstract noun.','word-formation')]);
P('seasonally','Seasonally is formed from seasonal + -ly; it means according to a yearly seasonal pattern or during a particular season.',C('seasonally.s1','环境','The river floods seasonally when snow melts in the upper valley.','上游山谷积雪融化时，河流会按季节规律泛滥。','flood/grow/change seasonally','副词表示按季节发生或变化。','flooding repeats in snowmelt season.','环境'),M('The river flooded seasonally in precisely the same way every hour of every day, with no link to any season.','The river flooded seasonally during the snowmelt period each year.','不与季节相关的固定每小时泛滥不叫seasonally。','meaning'),[Q(1,'A river that floods seasonally floods…','at a recurring time of year','randomly every minute with no pattern','only when its seaway is closed','Seasonally means in a seasonal pattern.','meaning'),Q(1,'Which sentence uses seasonally correctly?','The birds migrate seasonally as temperatures change.','The birds migrate seasonal as temperatures change.','The birds seasonal migrate ly.','Seasonally is the adverb modifying migrate.','grammar'),Q(1,'Farmers may plant a crop seasonally when…','the suitable part of the year returns','the crop is being sculpted from stone','the seabed is dry','Planting may follow the yearly growing cycle.','context'),Q(1,'Seasonally is formed from seasonal plus…','-ly','-ness','-er','The suffix -ly forms the adverb.','word-formation')]);
P('seasoned','Seasoned is formed from season + -ed; it describes food flavoured with spices or, figuratively, a person with extensive experience.',[C('seasoned.s1','烹饪','The chef served seasoned rice with herbs and toasted almonds.','厨师端上加了香草和烤杏仁调味的米饭。','seasoned food/rice; lightly seasoned','形容词，指已加入盐、香草或香料的食物。','flavourings added.','烹饪'),C('seasoned.s2','工作','A seasoned negotiator kept the discussion calm despite the late changes.','一位经验丰富的谈判专家即使面对临时变动也保持了讨论平和。','a seasoned professional/traveler','比喻指在某项工作或活动中经验丰富的。','many years of practice.','工作')],M('The seasoned negotiator was new to every meeting and had never handled a contract before.','The seasoned negotiator had years of experience handling contracts.','从未处理过合同的新手不叫经验丰富。','distinction'),[Q(1,'Seasoned rice is rice that…','has had salt, herbs, or spices added','has been left completely unflavoured','was cooked on the seafloor','Seasoned can describe food with added flavourings.','meaning'),Q(2,'A seasoned negotiator is…','experienced at negotiating','a person coated in salt','someone who has never negotiated','Seasoned figuratively means experienced.','context'),Q(1,'Which phrase is natural?','a seasoned traveler','a seasoning traveler','a seasonedly travel','Seasoned is an adjective modifying traveler.','grammar'),Q(2,'Which sentence uses the experience sense?','A seasoned captain handled the storm calmly.','The chef served seasoned vegetables.','Add seasoning to the soup.','A captain’s calm handling shows experience.','meaning')]);
P('seasoning','Seasoning is formed from season + -ing; it names flavouring ingredients added to food or the process of adding them while cooking.',[C('seasoning.s1','烹饪','A little seasoning brought out the sweetness of the tomatoes.','少量调味料衬出了番茄的甜味。','add/use seasoning; herbs and seasoning','名词，指加入食物的盐、香草或香料。','flavouring improves taste.','烹饪'),C('seasoning.s2','烹饪','Careful seasoning of the soup made the simple ingredients taste balanced.','仔细给汤调味后，简单的食材也呈现出平衡的味道。','seasoning of + dish; careful seasoning','名词也指烹饪时添加调料这一过程。','cook adjusts flavour.','烹饪')],M('The cook improved the soup’s seasoning by removing every herb and spice and adding nothing.','The cook improved the soup’s seasoning by adding measured herbs and salt.','去除所有调味料不会增加风味。','meaning'),[Q(1,'Seasoning in a recipe means…','salt, herbs, or spices added for flavour','the cooking pot itself','a list of seasonal jobs','Seasoning sense 1 names flavourings.','meaning'),Q(2,'Careful seasoning is the process of…','adjusting flavour by adding ingredients','scrutinizing a script','sealing a jar without opening it','Sense 2 is the act of flavouring during cooking.','context'),Q(1,'Which phrase is natural?','add seasoning to the soup','add seasoningly the soup','seasoning soup by to add','To introduces the dish receiving seasoning.','grammar'),Q(1,'Seasoning is formed from season plus…','-ing','-er','-al','The -ing form functions as a noun for flavourings or the process.','word-formation')]);
P('seat','Seat is related to Old Norse sæti and the Germanic family of sit; it means a place to sit, a position in a legislature, an organization’s base, or to arrange people in places.',[C('seat.s1','日常','Please take a seat while the receptionist finds your appointment.','接待员查找预约时，请先坐下。','take/have a seat; a seat for + person','名词，指供人坐的座位。','visitor sits in chair.','日常'),C('seat.s2','政治','She won a seat in parliament after the close district election.','她在势均力敌的选区选举后赢得了议会席位。','win/hold a seat in + parliament/committee','名词，指议会或委员会中的成员位置。','elected representative joins body.','政治'),C('seat.s3','机构','The city is the seat of government for the region.','这座城市是该地区的政府所在地。','the seat of + government/organization','名词，也指机构或活动的总部或基地。','government based in city.','机构'),C('seat.s4','场地','The hall seats two hundred people for the performance.','这座大厅可容纳两百人观看演出。','seat + number of people; be seated','动词，表示安排人就座或容纳一定数量座位。','venue capacity.','场地')],M('The hall seats two hundred people, but it has no chairs or space for anyone to sit.','The hall seats two hundred people with rows of chairs for the audience.','若没有座位或空间，就不能容纳观众就座。','meaning'),[Q(1,'Please take a seat means…','sit down in a place provided for sitting','win an election','become a seaport','Seat sense 1 is a place to sit.','meaning'),Q(2,'A seat in parliament is…','a position as a member of the legislature','a chair in a waiting room only','a coastal shipping route','Seat can name an elected position.','context'),Q(3,'The seat of government is…','the place where the government is based','a chair used by the prime minister','the government’s seaside holiday','Sense 3 means headquarters or base.','meaning'),Q(4,'The hall seats 200 means it…','has room for 200 people','has 200 elected politicians','is the government’s headquarters','As a verb, seat can state capacity.','meaning')]);
P('seawater','Seawater combines sea and water; it is the salty water that fills seas and oceans.',C('seawater.s1','海洋','Seawater is too salty to drink without removing the dissolved salts.','海水含盐太多，不除去溶解盐就不能饮用。','seawater temperature/salinity; desalinate seawater','名词，指海洋中的咸水。','ocean water contains salt.','海洋'),M('The bottle was filled with seawater, pure fresh water containing no dissolved salts.','The bottle was filled with salty ocean water.','无盐淡水不是seawater。','distinction'),[Q(1,'Seawater is…','salty water from the oceans','fresh water from a mountain spring','a seabird’s nest','Seawater contains dissolved salts.','meaning'),Q(1,'Why must seawater be treated before drinking?','Its salt concentration is too high.','It contains no water.','It is a solid seabed.','Desalination removes salt from seawater.','context'),Q(1,'Which phrase is natural?','test the seawater for salt','test seawaterly to salt','test the salt to seawater at','One can test seawater for its salt content.','grammar'),Q(1,'Seawater combines sea with…','water','weed','way','It names the water found in the sea.','word-formation')]);
P('seaway','Seaway combines sea and way; it is a route across the sea or a deep inland waterway open to ocean-going ships.',[C('seaway.s1','交通','The captain chose a northern seaway that avoided the worst winter storms.','船长选择了一条避开最猛烈冬季风暴的北方海上航线。','a sea/seaway route; navigate a seaway','名词，指船舶在海上的航路。','ship follows ocean route.','交通'),C('seaway.s1','交通','The Great Lakes seaway allows ocean ships to reach ports far inland.','五大湖水道让远洋船舶能够抵达内陆深处的港口。','an inland seaway; the seaway is open/closed','名词也指可供海船通行的深水内陆水路。','ocean vessels travel inland.','交通')],M('The Great Lakes seaway was closed to ocean ships because it was a dry road with no navigable water.','The Great Lakes seaway let ocean ships travel along a navigable inland waterway.','seaway必须是可通航的水路，不是干燥道路。','meaning'),[Q(1,'A seaway route is…','a route used by ships at sea','a trail across a dry mountain','a screen divider','Seaway sense 1 names a maritime route.','meaning'),Q(1,'An inland seaway allows…','ocean ships to travel along deep waterways into the interior','only small cars to cross a desert','fish to walk over a runway','The inland sense is a navigable channel for ships.','context'),Q(1,'Which phrase is natural?','navigate the seaway','navigate a seawayly','sea the waying navigate','Ships navigate along a seaway.','grammar'),Q(1,'Seaway combines sea with…','way','weed','seat','The compound names a route over or through water.','word-formation')]);
P('seaweed','Seaweed combines sea and weed; it is marine algae, often growing in large brown, green, or red masses.',C('seaweed.s1','自然','Farmers harvested seaweed from the rocks to use as fertilizer.','农民从岩石上收割海藻，用作肥料。','brown/green/red seaweed; seaweed grows on rocks','名词总称海中的藻类。','marine algae harvested.','自然'),M('The farmer called wheat seaweed, although wheat grows on land and is not marine algae.','The farmer called the algae growing on the rocks seaweed.','陆生小麦不是海藻。','distinction'),[Q(1,'Seaweed is…','marine algae','a sea mammal','a tool for tightening a screw','Seaweed refers to algae from marine environments.','meaning'),Q(1,'Farmers might harvest seaweed to…','use it as fertilizer','turn it into a scriptwriter','seal a dry envelope','Seaweed can be collected for agricultural use.','context'),Q(1,'Which phrase is natural?','brown seaweed on rocks','seaweedly brown to rocks','rocks of brown seascreen','Brown can describe one common type of seaweed.','grammar'),Q(1,'Seaweed combines sea with…','weed','wood','seaman','The compound names plant-like growth in the sea.','word-formation')]);
P('secede','From Latin secedere “withdraw, go apart,” from se- “apart” and cedere “go”; secede means formally leave a federation, alliance, or political state.',C('secede.s1','政治','The region voted to secede from the federation after years of negotiations.','经过多年谈判，该地区投票决定脱离联邦。','secede from + state/federation/organization','动词，指通过正式决定退出政治国家或联盟。','vote formalizes withdrawal.','政治'),M('The province seceded from the union by joining it more firmly and surrendering its independent status.','The province seceded from the union by formally withdrawing from it.','加入并放弃独立地位与脱离联盟相反。','meaning'),[Q(1,'To secede from a federation is to…','formally withdraw from it','join it as a new member','scrutinize its ballot papers','Secede means leave a political union formally.','meaning'),Q(1,'A region may vote to secede after…','deciding it wants to leave the union','receiving a seaway map','winning a seat in the same legislature only','A vote can authorize formal withdrawal.','context'),Q(1,'Which preposition is correct?','secede from the union','secede to the union','secede at the union','From marks the body being left.','grammar'),Q(1,'Latin se- in secede contributes the sense…','apart','salt','season','The prefix se- means apart or away.','word-formation')]);
P('secession','From Latin secessio, from secedere “withdraw”; secession is a formal withdrawal from a political state, federation, or organization.',C('secession.s1','政治','The proposed secession would separate the province from the national government.','拟议中的脱离行为将使该省与中央政府分开。','secession from + state/union; a secession movement','名词，指从国家或组织正式退出。','province seeks formal exit.','政治'),M('The country’s secession meant it had just joined the federation and agreed to remain under its government.','The country’s secession meant it formally withdrew from the federation.','加入联邦并继续留在其中与secession相反。','meaning'),[Q(1,'Secession is…','formal withdrawal from a political state or organization','the act of joining an alliance','a route used by seagoing ships','Secession means formally leaving a political body.','meaning'),Q(1,'A secession vote may lead to…','a region’s formal departure from a union','a region becoming a seaport','the union’s screenplay being published','Secession changes membership in the political state.','context'),Q(1,'Which phrase is natural?','secession from the federation','secession to the federation','secession of leaving from to','From identifies the state or body exited.','grammar'),Q(1,'Secession is the noun related to the verb…','secede','season','search','Secession names the act of seceding.','word-formation')]);
})();
